                  <td className="px-6 py-4 text-sm text-gray-500">{entry.listedOn}</td>
                </tr>
              ))}
              {paginatedData.length === 0 && (
                <tr>
                   <td colSpan={6} className="px-6 py-12 text-center text-gray-400">
                     No records found matching your search.
                   </td>
                </tr>
