  const [copiedLink, setCopiedLink] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Sync local settings with prop settings only if user hasn't made unsaved changes
  useEffect(() => {
    if (!hasChanges) {
