const fromSupabaseFormat = (data: any): Client => {
  return {
    id: data.id,
    no: data["No"] || '',
    status: data["Status"] || 'Pending',
    qfcNo: data["QFC No"] || '',
    legalStructure: data["Legal Structure"] || '',
