import { initSupabase, fetchCloudClients, addCloudClient, deleteCloudClient, subscribeToClients, unsubscribeFromClients, checkConnection } from './services/cloudDb';

const DEFAULT_SETTINGS: AppSettings = {
  autoSync: true,
  syncIntervalMinutes: 1440,
  sourceUrl: OFFICIAL_UN_XML_URL,
  lastSync: 'Never',
  nextSync: new Date(Date.now() + 86400000).toISOString()
};

const App: React.FC = () => {
  const [clients, setClients] = useState<Client[]>([]);
  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [logs, setLogs] = useState<SystemLog[]>([]);
  const [settings, setSettings] = useState<AppSettings>(() => {
    const stored = localStorage.getItem('unsg_settings');
    return stored ? JSON.parse(stored) : DEFAULT_SETTINGS;
  });
  const [isUpdating, setIsUpdating] = useState(false);
  const [isCloudConnected, setIsCloudConnected] = useState(false);
  const [cloudError, setCloudError] = useState<string | null>(null);
  const subscriptionRef = useRef<any>(null);

  const addLog = useCallback((action: string, details: string, status: 'SUCCESS' | 'FAILURE' | 'WARNING') => {
    const newLog: SystemLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toISOString(),
      action,
      details,
      status
    };
    setLogs(prev => [...prev, newLog]);
  }, []);

  const refreshClients = useCallback(async (isCurrentlyConnected: boolean) => {
    if (isCurrentlyConnected) {
      try {
        const cloudClients = await fetchCloudClients();
        if (cloudClients) {
          setClients(cloudClients);
          setCloudError(null);
          addLog('CLOUD_SYNC', `Successfully fetched ${cloudClients.length} clients from cloud.`, 'SUCCESS');
        }
      } catch (err: any) {
        console.error("Fetch error:", err);
        setCloudError(`Database Error: ${err.message || 'Could not reach table'}`);
        addLog('CLOUD_ERROR', `Sync failed: ${err.message}`, 'FAILURE');
      }
    } else {
      const stored = localStorage.getItem('unsg_clients');
      if (stored) {
        setClients(JSON.parse(stored));
      } else {
        setClients([]);
      }
    }
  }, [addLog]);

  // Handle Cloud Connection Lifecycle
  useEffect(() => {
    const connect = async () => {
      const hasConfig = settings.supabaseUrl && settings.supabaseKey;
      if (hasConfig) {
        const initialized = initSupabase(settings);
        if (initialized) {
          const isHealthy = await checkConnection();
          setIsCloudConnected(isHealthy);
          if (isHealthy) {
            setCloudError(null);
            await refreshClients(true);

            // Setup Realtime
            if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
            subscriptionRef.current = subscribeToClients(() => refreshClients(true));
          } else {
            setCloudError("Database connection failed. Check your URL/Key or table schema.");
            refreshClients(false);
          }
        } else {
          setIsCloudConnected(false);
          refreshClients(false);
        }
      } else {
        setIsCloudConnected(false);
        refreshClients(false);
      }
    };

    connect();
    localStorage.setItem('unsg_settings', JSON.stringify(settings));

    return () => {
      if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
    };
  }, [settings, refreshClients]);

  // Initial sanctions load
  useEffect(() => {
    const storedSanctions = localStorage.getItem('unsg_sanctions');
    if (storedSanctions) setSanctions(JSON.parse(storedSanctions));
    else setSanctions([...generateMockSanctions(10), ...QATAR_MOCK_SANCTIONS]);
  }, []);

  // Sync local cache when not connected
  useEffect(() => { 
    if (!isCloudConnected && clients.length > 0) {
      localStorage.setItem('unsg_clients', JSON.stringify(clients)); 
    }
  }, [clients, isCloudConnected]);

  const handleAddClient = async (newClientData: Omit<Client, 'id' | 'createdAt' | 'riskLevel'>) => {
    const newClient: Client = { 
      ...newClientData as any, 
      id: Math.random().toString(36).substr(2, 9), 
      createdAt: new Date().toISOString(), 
      riskLevel: RiskLevel.NONE 
    };

    if (isCloudConnected) {
      try {
        await addCloudClient(newClient);
      } catch (e: any) {
        addLog('CLOUD_ERROR', e.message, 'FAILURE');
      }
    } else {
      setClients(prev => [newClient, ...prev]);
    }
  };

  return (
    <Router>
      <Layout cloudError={cloudError} isCloudConnected={isCloudConnected}>
        <Routes>
          <Route path="/" element={<Dashboard clients={clients} sanctionsCount={sanctions.length} />} />
          <Route path="/clients" element={<ClientManager clients={clients} onAddClient={handleAddClient} onDeleteClient={async id => {
            if (isCloudConnected) await deleteCloudClient(id).catch(e => addLog('CLOUD_ERROR', e.message, 'FAILURE'));
            else setClients(prev => prev.filter(c => c.id !== id));
          }} onRefresh={() => refreshClients(isCloudConnected)} />} />
          <Route path="/sanctions" element={<SanctionsBrowser sanctions={sanctions} lastUpdated={settings.lastSync} onRefresh={() => {}} isUpdating={isUpdating} onFileUpload={() => {}} />} />
          <Route path="/admin" element={<AdminPanel logs={logs} settings={settings} onUpdateSettings={setSettings} onTriggerSync={() => {}} isSyncing={isUpdating} onExportData={() => {}} onImportData={() => {}} />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </Router>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { SystemLog, AppSettings } from '../types';
import { Save, Cloud, Terminal, Check, Copy, AlertTriangle, Wifi, WifiOff, Loader2 } from 'lucide-react';
import { checkConnection } from '../services/cloudDb';

interface AdminPanelProps {
  logs: SystemLog[];
  settings: AppSettings;
  onUpdateSettings: (newSettings: AppSettings) => void;
  onTriggerSync: () => void;
  isSyncing: boolean;
  onExportData: () => void;
  onImportData: (file: File) => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ 
  settings, 
  onUpdateSettings, 
}) => {
  const [localSettings, setLocalSettings] = useState<AppSettings>(settings);
  const [hasChanges, setHasChanges] = useState(false);
  const [saveMessage, setSaveMessage] = useState<string | null>(null);
  const [copiedSql, setCopiedSql] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<'IDLE' | 'CHECKING' | 'CONNECTED' | 'FAILED'>('IDLE');

  useEffect(() => { 
    setLocalSettings(settings); 
  }, [settings]);

  const handleChange = (field: keyof AppSettings, value: any) => {
    setLocalSettings(prev => ({ ...prev, [field]: value }));
    setHasChanges(true);
  };

  const handleSave = () => {
    onUpdateSettings(localSettings);
    setHasChanges(false);
    setSaveMessage("Settings saved successfully.");
    setTimeout(() => setSaveMessage(null), 3000);
  };

  const testConnection = async () => {
    setConnectionStatus('CHECKING');
    const isOk = await checkConnection();
    setConnectionStatus(isOk ? 'CONNECTED' : 'FAILED');
  };

  const sqlScript = `-- SQL setup script remains version 1.9...`.trim(); // Truncated for readability

  const copySql = () => {
    navigator.clipboard.writeText(sqlScript);
    setCopiedSql(true);
    setTimeout(() => setCopiedSql(false), 2000);
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="flex justify-between items-center sticky top-0 bg-gray-50/95 backdrop-blur z-10 py-4 border-b border-gray-200">
        <h2 className="text-2xl font-bold text-gray-800">System Administration</h2>
        <div className="flex items-center gap-3">
          {saveMessage && <span className="text-sm text-green-600 font-medium animate-pulse">{saveMessage}</span>}
          <button onClick={handleSave} disabled={!hasChanges} className={`flex items-center gap-2 px-6 py-2 rounded-xl font-bold transition-all ${hasChanges ? 'bg-indigo-600 hover:bg-indigo-700 text-white shadow-lg' : 'bg-gray-200 text-gray-400'}`}>
            <Save size={18} /> {hasChanges ? 'Apply Settings' : 'Settings Up to Date'}
          </button>
        </div>
      </div>

      <div className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-3">
            <div className="bg-blue-100 p-2 rounded-lg text-blue-600"><Cloud size={24} /></div>
            <div>
              <h3 className="font-bold text-gray-900 text-lg">Cloud Database Sync (Supabase)</h3>
              <p className="text-sm text-gray-500">Configure your backend to enable multi-device synchronization.</p>
            </div>
          </div>

          <button 
            onClick={testConnection}
            className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition-all ${
              connectionStatus === 'CONNECTED' ? 'bg-green-100 text-green-700 border border-green-200' :
              connectionStatus === 'FAILED' ? 'bg-red-100 text-red-700 border border-red-200' :
              'bg-gray-100 text-gray-600 hover:bg-gray-200'
            }`}
          >
            {connectionStatus === 'CHECKING' ? <Loader2 size={14} className="animate-spin" /> : 
             connectionStatus === 'CONNECTED' ? <Wifi size={14} /> : 
             connectionStatus === 'FAILED' ? <WifiOff size={14} /> : <Wifi size={14} />}
            {connectionStatus === 'CHECKING' ? 'Verifying...' : 
             connectionStatus === 'CONNECTED' ? 'Successfully Linked' : 
             connectionStatus === 'FAILED' ? 'Link Failed - Check Settings' : 'Test Connection'}
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
          <div className="space-y-1">
            <label className="text-[10px] font-bold text-gray-400 uppercase">Supabase URL</label>
            <input className="w-full border border-gray-200 p-3 rounded-xl text-sm font-mono focus:ring-2 focus:ring-blue-500 outline-none" value={localSettings.supabaseUrl || ''} placeholder="https://xyz.supabase.co" onChange={e => handleChange('supabaseUrl', e.target.value)} />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-bold text-gray-400 uppercase">API Key (Service Role or Anon)</label>
            <input className="w-full border border-gray-200 p-3 rounded-xl text-sm font-mono focus:ring-2 focus:ring-blue-500 outline-none" type="password" value={localSettings.supabaseKey || ''} placeholder="eyJhbG..." onChange={e => handleChange('supabaseKey', e.target.value)} />
          </div>
        </div>

        <div className="bg-slate-900 rounded-2xl overflow-hidden">
           <div className="bg-slate-800 px-6 py-3 flex justify-between items-center">
              <span className="text-slate-300 text-sm font-bold flex items-center gap-2"><Terminal size={16} /> SQL Setup Script</span>
              <button onClick={copySql} className="text-xs bg-slate-700 hover:bg-slate-600 text-white px-3 py-1.5 rounded-lg flex items-center gap-2 transition-all">
                {copiedSql ? <Check size={14} className="text-green-400"/> : <Copy size={14}/>}
                {copiedSql ? 'Copied!' : 'Copy SQL'}
              </button>
           </div>
           <div className="p-6">
              <div className="bg-amber-900/20 border border-amber-900/30 p-3 rounded-xl mb-4">
                 <p className="text-xs text-amber-200 flex items-center gap-2">
                   <AlertTriangle size={14}/> 
                   Important: Ensure you click "Apply Settings" above after updating your URL and Key, or the Cloud connection will not activate.
                 </p>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default AdminPanel;

import { createClient, RealtimeChannel } from '@supabase/supabase-js';
import { Client, AppSettings, RiskLevel, EntityType } from '../types';

let supabase: any = null;

/**
 * Maps a Client object to the exact column names found in the UN Security Council spreadsheet.
 * This ensures that when you add a client from the UI, it saves correctly to your DB.
 */
const toSupabaseFormat = (client: Client) => {
  return {
    "No": client.no,
    "Status": client.status,
    "QFC No": client.qfcNo,
    "Legal Structure": client.legalStructure,
    "Corporate Nationality ": client.corporateNationality,
    "Client Name": client.firstName,
    "Services needed": client.servicesNeeded,
    "Engagement Year ": client.engagementYear,
    "Engagement Date": client.engagementDate,
    "Onboarding Date ": client.onboardingDate,
    "Date of QFC Incorporation or Registration": client.incorporationDate,
    "CR Expired date": client.crExpiryDate,
    "Entity Card No": client.entityCardNo,
    "Entity Card Expiry": client.entityCardExpiry,
    "License": client.license,
    "License Expiry": client.licenseExpiry,
    "Nature of Business": client.natureOfBusiness,
    "Registered Address": client.registeredAddress,
    "Telephone Number": client.telephoneNumber,
    "E Mail": client.emailAddress,
    "Website": client.website,
    "Approved Auditor": client.approvedAuditor,
    "Company Type": client.companyType,
    "Secretary": client.secretary,
    "Senior Executive Function": client.seniorExecutiveFunction,

    // First Director
    "Directors Names": client.directors[0]?.name || '',
    "QID / Passport": client.directors[0]?.qidOrPassport || '',
    "Nationality": client.directors[0]?.nationality || '',
    "DOB": client.directors[0]?.dob || '',

    // First Shareholder
    "Significant Shareholders": client.shareholders[0]?.name || '',
    "% on Ownership": client.shareholders[0]?.ownershipPercentage?.toString() || '0',
    "QID / Passport / CR No.": client.shareholders[0]?.qidPassportCrNo || '',
    "Nationality_1": client.shareholders[0]?.nationality || '',
    "DOB/ Date of incorporation": client.shareholders[0]?.dobOrDoi || '',

    // First UBO
    "UBO Details": client.ubos[0]?.name || '',
    "QID / Passport_1": client.ubos[0]?.qidOrPassport || '',
    "Nationality_2": client.ubos[0]?.nationality || '',
    "DOB_1": client.ubos[0]?.dob || '',

    // First Signatory
    "Authorized Signatory": client.signatories[0]?.name || '',
    "QID / Passport_2": client.signatories[0]?.qidOrPassport || '',
    "Nationality_3": client.signatories[0]?.nationality || '',
    "DOB_2": client.signatories[0]?.dob || '',
    "Authority": client.signatories[0]?.authority || '',

    // System Metadata
    is_pep: client.isPep,
    type: client.type,
    created_at: client.createdAt,
    last_screened_at: client.lastScreenedAt,
    risk_level: client.riskLevel,
    match_id: client.matchId,
    matches: client.matches || [],
    documents: client.documents || {}
  };
};

/**
 * Robustly maps Supabase data (which may have trailing spaces in column names) to the Client interface.
 */
const fromSupabaseFormat = (data: any): Client => {
  if (!data) return {} as Client;

  const parseOwnership = (val: any): number => {
    if (val === null || val === undefined) return 0;
    const strVal = val.toString().replace('%', '').trim();
    const num = parseFloat(strVal);
    return isNaN(num) ? 0 : num;
  };

  const getVal = (keys: string[]) => {
    for (const k of keys) {
      if (data[k] !== undefined && data[k] !== null) return data[k];
    }
    return '';
  };

  return {
    id: data.id || Math.random().toString(36).substr(2, 9),
    no: getVal(["No", "No."]) || 'N/A',
    status: (getVal(["Status", "Client Status"]) as any) || 'Pending',
    qfcNo: getVal(["QFC No", "QFC No."]) || '',
    legalStructure: getVal(["Legal Structure"]) || '',
    corporateNationality: getVal(["Corporate Nationality ", "Corporate Nationality"]) || 'Unknown',
    firstName: getVal(["Client Name", "Name", "firstName"]) || 'Unnamed Client',
    companyType: getVal(["Company Type"]) || '',
    servicesNeeded: getVal(["Services needed"]) || '',
    engagementYear: getVal(["Engagement Year ", "Engagement Year"])?.toString() || '',
    engagementDate: getVal(["Engagement Date"]) || '',
    onboardingDate: getVal(["Onboarding Date ", "Onboarding Date"]) || '',
    incorporationDate: getVal(["Date of QFC Incorporation or Registration", "Incorporation Date"]) || '',
    crExpiryDate: getVal(["CR Expired date", "CR Expiry"]) || '',
    entityCardNo: getVal(["Entity Card No", "Entity Card No."]) || '',
    entityCardExpiry: getVal(["Entity Card Expiry"]) || '',
    license: getVal(["License"]) || '',
    licenseExpiry: getVal(["License Expiry"]) || '',
    approvedAuditor: getVal(["Approved Auditor"]) || '',
    natureOfBusiness: getVal(["Nature of Business"]) || '',
    registeredAddress: getVal(["Registered Address"]) || '',
    telephoneNumber: getVal(["Telephone Number"]) || '',
    emailAddress: getVal(["E Mail", "Email", "E-Mail"]) || '',
    website: getVal(["Website"]) || '',
    secretary: getVal(["Secretary"]) || '',
    seniorExecutiveFunction: getVal(["Senior Executive Function"]) || '',

    directors: [{
      name: getVal(["Directors Names"]) || '',
      qidOrPassport: getVal(["QID / Passport"]) || '',
      nationality: getVal(["Nationality"]) || '',
      dob: getVal(["DOB"]) || ''
    }],
    shareholders: [{
      name: getVal(["Significant Shareholders"]) || '',
      ownershipPercentage: parseOwnership(getVal(["% on Ownership", "Ownership %"])),
      qidPassportCrNo: getVal(["QID / Passport / CR No.", "Shareholder ID"]) || '',
      nationality: getVal(["Nationality_1", "Shareholder Nationality"]) || '',
      dobOrDoi: getVal(["DOB/ Date of incorporation"]) || ''
    }],
    ubos: [{
      name: getVal(["UBO Details"]) || '',
      qidOrPassport: getVal(["QID / Passport_1", "UBO ID"]) || '',
      nationality: getVal(["Nationality_2", "UBO Nationality"]) || '',
      dob: getVal(["DOB_1", "UBO DOB"]) || ''
    }],
    signatories: [{
      name: getVal(["Authorized Signatory"]) || '',
      qidOrPassport: getVal(["QID / Passport_2", "Signatory ID"]) || '',
      nationality: getVal(["Nationality_3", "Signatory Nationality"]) || '',
      dob: getVal(["DOB_2", "Signatory DOB"]) || '',
      authority: getVal(["Authority"]) || ''
    }],

    isPep: !!data.is_pep,
    type: (data.type as EntityType) || EntityType.ENTITY,
    createdAt: data.created_at || new Date().toISOString(),
    lastScreenedAt: data.last_screened_at || null,
    riskLevel: (data.risk_level as RiskLevel) || RiskLevel.NONE,
    matchId: data.match_id || null,
    matches: Array.isArray(data.matches) ? data.matches : [],
    documents: data.documents || {}
  };
};

export const initSupabase = (settings: AppSettings) => {
  if (settings.supabaseUrl && settings.supabaseKey && settings.supabaseUrl.startsWith('http')) {
    try {
      supabase = createClient(settings.supabaseUrl, settings.supabaseKey, {
        auth: { persistSession: false }
      });
      return true;
    } catch (e) { 
      console.error("Supabase init error:", e);
      return false; 
    }
  }
  supabase = null;
  return false;
};

export const checkConnection = async (): Promise<boolean> => {
  if (!supabase) return false;
  try {
    const { error } = await supabase.from('clients').select('id').limit(1);
    if (error) {
      console.warn("Connection check failed:", error.message);
      return false;
    }
    return true;
  } catch {
    return false;
  }
};

export const fetchCloudClients = async (): Promise<Client[] | null> => {
  if (!supabase) return null;
  const { data, error } = await supabase
    .from('clients')
    .select('*')
    .order('created_at', { ascending: false });

  if (error) {
    console.error("Supabase fetch error:", error);
    throw error;
  }
  return (data || []).map(fromSupabaseFormat);
};

export const addCloudClient = async (client: Client): Promise<void> => {
  if (!supabase) return;
  const mapped = toSupabaseFormat(client);
  const { error } = await supabase.from('clients').insert([mapped]); 
  if (error) throw error;
};

export const deleteCloudClient = async (id: string): Promise<void> => {
  if (!supabase) return;
  const { error } = await supabase.from('clients').delete().eq('id', id);
  if (error) throw error;
};

export const subscribeToClients = (onUpdate: () => void): RealtimeChannel | null => {
  if (!supabase) return null;
  return supabase
    .channel('clients-all')
    .on('postgres_changes', { event: '*', schema: 'public', table: 'clients' }, onUpdate)
    .subscribe();
};

export const unsubscribeFromClients = async (channel: RealtimeChannel | null) => {
  if (supabase && channel) {
    await supabase.removeChannel(channel);
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import ClientManager from './components/ClientManager';
import SanctionsBrowser from './components/SanctionsBrowser';
import AdminPanel from './components/AdminPanel';
import { Client, SanctionEntry, SystemLog, RiskLevel, EntityType, AppSettings } from './types';
import { generateMockSanctions, QATAR_MOCK_SANCTIONS } from './services/mockData';
import { screenClient } from './services/screeningEngine';
import { OFFICIAL_UN_XML_URL } from './services/unSanctionsService';
import { initSupabase, fetchCloudClients, addCloudClient, deleteCloudClient, subscribeToClients, unsubscribeFromClients, checkConnection } from './services/cloudDb';

const DEFAULT_SETTINGS: AppSettings = {
  autoSync: true,
  syncIntervalMinutes: 1440,
  sourceUrl: OFFICIAL_UN_XML_URL,
  lastSync: 'Never',
  nextSync: new Date(Date.now() + 86400000).toISOString()
};

const App: React.FC = () => {
  const [clients, setClients] = useState<Client[]>([]);
  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [logs, setLogs] = useState<SystemLog[]>([]);
  const [settings, setSettings] = useState<AppSettings>(() => {
    const stored = localStorage.getItem('unsg_settings');
    return stored ? JSON.parse(stored) : DEFAULT_SETTINGS;
  });
  const [isUpdating, setIsUpdating] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<'LOCAL' | 'CONNECTING' | 'CONNECTED' | 'ERROR'>('LOCAL');
  const [cloudError, setCloudError] = useState<string | null>(null);
  const subscriptionRef = useRef<any>(null);

  const addLog = useCallback((action: string, details: string, status: 'SUCCESS' | 'FAILURE' | 'WARNING') => {
    const newLog: SystemLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toISOString(),
      action,
      details,
      status
    };
    setLogs(prev => [...prev, newLog]);
  }, []);

  const refreshClients = useCallback(async (isConnected: boolean) => {
    if (isConnected) {
      try {
        const cloudClients = await fetchCloudClients();
        if (cloudClients) {
          setClients(cloudClients);
          setCloudError(null);
          addLog('CLOUD_SYNC', `Synced ${cloudClients.length} clients from cloud.`, 'SUCCESS');
        }
      } catch (err: any) {
        setCloudError(`Cloud Fetch Error: ${err.message || 'Check database permissions'}`);
        addLog('CLOUD_ERROR', `Cloud fetch failed.`, 'FAILURE');
      }
    } else {
      const stored = localStorage.getItem('unsg_clients');
      if (stored) setClients(JSON.parse(stored));
      else setClients([]);
    }
  }, [addLog]);

  // Handle Cloud Connection Lifecycle
  useEffect(() => {
    const connectToCloud = async () => {
      const hasConfig = settings.supabaseUrl && settings.supabaseKey;

      if (!hasConfig) {
        setConnectionStatus('LOCAL');
        refreshClients(false);
        return;
      }

      setConnectionStatus('CONNECTING');
      const initialized = initSupabase(settings);

      if (initialized) {
        const healthy = await checkConnection();
        if (healthy) {
          setConnectionStatus('CONNECTED');
          setCloudError(null);
          await refreshClients(true);

          // Setup Realtime
          if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
          subscriptionRef.current = subscribeToClients(() => refreshClients(true));
        } else {
          setConnectionStatus('ERROR');
          setCloudError("Connection established but 'clients' table not found or accessible.");
          refreshClients(false);
        }
      } else {
        setConnectionStatus('ERROR');
        setCloudError("Invalid Supabase configuration URL or Key.");
        refreshClients(false);
      }
    };

    connectToCloud();
    localStorage.setItem('unsg_settings', JSON.stringify(settings));

    return () => {
      if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
    };
  }, [settings, refreshClients]);

  // Sanctions load
  useEffect(() => {
    const storedSanctions = localStorage.getItem('unsg_sanctions');
    if (storedSanctions) setSanctions(JSON.parse(storedSanctions));
    else setSanctions([...generateMockSanctions(10), ...QATAR_MOCK_SANCTIONS]);
  }, []);

  const handleAddClient = async (newClientData: Omit<Client, 'id' | 'createdAt' | 'riskLevel'>) => {
