                className="p-2.5 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 disabled:opacity-30 disabled:cursor-not-allowed text-gray-500 transition-all shadow-sm"
              >
                <ChevronsLeft size={16} />
              </button>
              <button 
                onClick={() => handlePageChange(currentPage - 1)} 
                disabled={currentPage === 1}
                className="p-2.5 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 disabled:opacity-30 disabled:cursor-not-allowed text-gray-500 transition-all shadow-sm"
              >
                <ChevronLeft size={16} />
              </button>

              <div className="px-4 py-2 text-xs font-black text-gray-700 bg-white rounded-xl border border-gray-200 shadow-sm min-w-[120px] text-center">
                Page {currentPage} / {totalPages}
              </div>

              <button 
                onClick={() => handlePageChange(currentPage + 1)} 
                disabled={currentPage === totalPages}
                className="p-2.5 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 disabled:opacity-30 disabled:cursor-not-allowed text-gray-500 transition-all shadow-sm"
              >
                <ChevronRight size={16} />
              </button>
              <button 
                onClick={() => handlePageChange(totalPages)} 
                disabled={currentPage === totalPages}
                className="p-2.5 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 disabled:opacity-30 disabled:cursor-not-allowed text-gray-500 transition-all shadow-sm"
              >
                <ChevronsRight size={16} />
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

