    }
  };

  const [formData, setFormData] = useState(initialFormData);

  const handleManualRefresh = async () => {
    setIsRefreshing(true);
    await onRefresh();
    setTimeout(() => setIsRefreshing(false), 800);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAddClient(formData);
    setFormData(initialFormData);
    setIsModalOpen(false);
  };

  const addRow = (section: 'directors' | 'shareholders' | 'ubos' | 'signatories' | 'servicesNeeded') => {
    if (section === 'servicesNeeded') {
      setFormData({ ...formData, servicesNeeded: [...formData.servicesNeeded, ''] });
      return;
    }
    const newRows = [...formData[section]];
    const template: any = section === 'directors' ? { name: '', qidOrPassport: '', nationality: '', dob: '' } :
                      section === 'shareholders' ? { name: '', ownershipPercentage: 0, qidPassportCrNo: '', nationality: '', dobOrDoi: '', type: 'Individual' } :
                      section === 'ubos' ? { name: '', qidOrPassport: '', nationality: '', dob: '' } :
                      { name: '', qidOrPassport: '', nationality: '', dob: '', authority: '' };
    setFormData({ ...formData, [section]: [...newRows, template] });
  };

  const removeRow = (section: 'directors' | 'shareholders' | 'ubos' | 'signatories' | 'servicesNeeded', index: number) => {
    if (section === 'servicesNeeded') {
      const filtered = formData.servicesNeeded.filter((_, i) => i !== index);
      setFormData({ ...formData, servicesNeeded: filtered });
      return;
    }
    const filtered = (formData[section] as any[]).filter((_, i) => i !== index);
    setFormData({ ...formData, [section]: filtered });
  };

  const updateRow = (section: 'directors' | 'shareholders' | 'ubos' | 'signatories' | 'servicesNeeded', index: number, field: string, value: any) => {
    if (section === 'servicesNeeded') {
      const updated = [...formData.servicesNeeded];
      updated[index] = value;
      setFormData({ ...formData, servicesNeeded: updated });
      return;
    }
    const updated = [...(formData[section] as any[])];
    updated[index][field] = value;
    setFormData({ ...formData, [section]: updated });
  };

  const getRiskBadge = (risk: RiskLevel) => {
    switch (risk) {
      case RiskLevel.HIGH: return <span className="px-2 py-1 rounded-full text-[10px] font-bold bg-red-100 text-red-800 flex items-center gap-1"><ShieldAlert size={10}/> High Risk</span>;
      case RiskLevel.MEDIUM: return <span className="px-2 py-1 rounded-full text-[10px] font-bold bg-yellow-100 text-yellow-800 flex items-center gap-1"><AlertTriangle size={10}/> Medium</span>;
      default: return <span className="px-2 py-1 rounded-full text-[10px] font-bold bg-green-100 text-green-800 flex items-center gap-1"><CheckCircle2 size={10}/> Clean</span>;
    }
  };

  const filteredClients = clients.filter(c => 
    c.firstName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    c.no?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    c.qfcNo?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">Client Compliance & Onboarding</h2>
          <p className="text-sm text-gray-500">Corporate KYC Lifecycle Management</p>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={handleManualRefresh} 
            className={`flex items-center gap-2 bg-white border border-gray-200 px-4 py-3 rounded-2xl transition-all shadow-sm font-bold text-gray-600 hover:bg-gray-50 ${isRefreshing ? 'opacity-50' : ''}`}
          >
            <RefreshCw size={18} className={isRefreshing ? 'animate-spin' : ''} />
            Sync DB
          </button>
          <button onClick={() => setIsModalOpen(true)} className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-3 rounded-2xl transition-all shadow-xl shadow-indigo-100 font-bold">
            <Plus size={20} /> Start New Onboarding
          </button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex gap-4 items-center">
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Search clients by name, reference, or QFC number..." 
            className="w-full pl-12 pr-4 py-3 border-none bg-gray-50/50 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* Main Table Container - Reordered Columns */}
      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden overflow-x-auto">
        <table className="w-full text-left border-collapse min-w-[1400px]">
          <thead className="bg-gray-50/50 text-gray-400 border-b border-gray-100">
            <tr>
              <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest">No</th>
              <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest">Status</th>
              <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest">QFC No</th>
              <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest">Legal Structure</th>
              <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest">Corp. Nationality</th>
              <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest">Client Name</th>
              <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest">Services Needed</th>
              <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest">Eng. Year</th>
              <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest">Eng. Date</th>
              <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {filteredClients.map((client) => (
              <tr key={client.id} className="hover:bg-indigo-50/30 transition-colors group cursor-pointer" onClick={() => setSelectedClient(client)}>
                <td className="px-6 py-5 text-xs font-mono font-bold text-gray-600">{client.no}</td>
                <td className="px-6 py-5">
                  <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                    client.status === 'Active' ? 'bg-green-100 text-green-700' : 
                    client.status === 'Blacklisted' ? 'bg-red-100 text-red-700' :
                    'bg-blue-100 text-blue-700'
                  }`}>
                    {client.status}
                  </span>
                </td>
                <td className="px-6 py-5 text-xs text-gray-500 font-medium">{client.qfcNo || '—'}</td>
                <td className="px-6 py-5 text-xs text-gray-600 font-medium">{client.legalStructure}</td>
                <td className="px-6 py-5 text-xs text-gray-600 font-medium">{client.corporateNationality}</td>
                <td className="px-6 py-5">
                  <div className="font-bold text-gray-900 group-hover:text-indigo-600 transition-colors">{client.firstName}</div>
                </td>
                <td className="px-6 py-5">
                  <div className="flex flex-wrap gap-1 max-w-[200px]">
                    {client.servicesNeeded.slice(0, 2).map((s, i) => (
                      <span key={i} className="px-1.5 py-0.5 bg-gray-100 text-[9px] text-gray-500 rounded font-bold uppercase truncate">{s}</span>
                    ))}
                    {client.servicesNeeded.length > 2 && <span className="text-[9px] text-gray-400 font-bold">+{client.servicesNeeded.length - 2}</span>}
                    {client.servicesNeeded.length === 0 && <span className="text-xs text-gray-300 italic">—</span>}
                  </div>
                </td>
                <td className="px-6 py-5 text-xs text-gray-600 font-medium">{client.engagementYear}</td>
                <td className="px-6 py-5 text-xs text-gray-500 font-medium">{client.engagementDate || '—'}</td>
                <td className="px-6 py-5 text-right" onClick={(e) => e.stopPropagation()}>
                  <div className="flex justify-end gap-2">
                    <button onClick={() => setSelectedClient(client)} className="p-2 text-indigo-500 hover:text-indigo-700 hover:bg-indigo-50 rounded-lg transition-all"><Eye size={18}/></button>
                    <button onClick={() => onDeleteClient(client.id)} className="p-2 text-gray-400 hover:text-red-600 hover:bg-white rounded-lg transition-all"><Trash2 size={16}/></button>
                  </div>
                </td>
              </tr>
            ))}
            {filteredClients.length === 0 && (
              <tr>
                <td colSpan={10} className="px-6 py-20 text-center text-gray-400 italic">No matching client records found.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Detail Modal - Shows Full Information */}
      {selectedClient && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col overflow-hidden animate-in fade-in zoom-in duration-200">
            <div className="px-8 py-6 bg-slate-900 text-white flex justify-between items-center shrink-0">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-indigo-500/20 rounded-2xl text-indigo-400"><Building2 size={24}/></div>
                <div>
                  <h3 className="text-xl font-bold">{selectedClient.firstName}</h3>
                  <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Client Dossier • Ref: {selectedClient.no}</p>
                </div>
              </div>
              <button onClick={() => setSelectedClient(null)} className="text-slate-400 hover:text-white p-2 rounded-full hover:bg-white/10 transition-all"><X size={24}/></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar bg-gray-50/50">
              {/* Profile Grid */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm space-y-4">
                   <h4 className="text-[10px] font-black text-indigo-600 uppercase tracking-widest flex items-center gap-2"><Globe size={14}/> Registry Details</h4>
                   <div className="grid grid-cols-2 gap-4">
                      <div><p className="text-[9px] text-gray-400 font-bold uppercase">Status</p><p className="text-sm font-bold text-gray-800">{selectedClient.status}</p></div>
                      <div><p className="text-[9px] text-gray-400 font-bold uppercase">QFC Number</p><p className="text-sm font-bold text-gray-800">{selectedClient.qfcNo || 'N/A'}</p></div>
                      <div><p className="text-[9px] text-gray-400 font-bold uppercase">Nationality</p><p className="text-sm font-bold text-gray-800">{selectedClient.corporateNationality}</p></div>
                      <div><p className="text-[9px] text-gray-400 font-bold uppercase">Structure</p><p className="text-sm font-bold text-gray-800">{selectedClient.legalStructure}</p></div>
                   </div>
                </div>

                <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm space-y-4">
                   <h4 className="text-[10px] font-black text-indigo-600 uppercase tracking-widest flex items-center gap-2"><Calendar size={14}/> Timeline & Dates</h4>
                   <div className="grid grid-cols-2 gap-4">
                      <div><p className="text-[9px] text-gray-400 font-bold uppercase">Engagement Year</p><p className="text-sm font-bold text-gray-800">{selectedClient.engagementYear}</p></div>
                      <div><p className="text-[9px] text-gray-400 font-bold uppercase">Engagement Date</p><p className="text-sm font-bold text-gray-800">{selectedClient.engagementDate || 'N/A'}</p></div>
                      <div><p className="text-[9px] text-gray-400 font-bold uppercase">CR Expiry</p><p className="text-sm font-bold text-red-600">{selectedClient.crExpiryDate || 'N/A'}</p></div>
                      <div><p className="text-[9px] text-gray-400 font-bold uppercase">Onboarding Date</p><p className="text-sm font-bold text-gray-800">{selectedClient.onboardingDate || 'N/A'}</p></div>
                   </div>
                </div>
              </div>

              {/* Contact & Professional Info */}
              <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm space-y-4">
                <h4 className="text-[10px] font-black text-indigo-600 uppercase tracking-widest flex items-center gap-2"><Mail size={14}/> Communication & Audit</h4>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div><p className="text-[9px] text-gray-400 font-bold uppercase">Email</p><p className="text-sm font-bold text-gray-800">{selectedClient.emailAddress}</p></div>
                  <div><p className="text-[9px] text-gray-400 font-bold uppercase">Phone</p><p className="text-sm font-bold text-gray-800">{selectedClient.telephoneNumber}</p></div>
                  <div><p className="text-[9px] text-gray-400 font-bold uppercase">Auditor</p><p className="text-sm font-bold text-gray-800">{selectedClient.approvedAuditor || 'None Assigned'}</p></div>
                  <div className="md:col-span-3"><p className="text-[9px] text-gray-400 font-bold uppercase">Registered Address</p><p className="text-sm font-bold text-gray-800">{selectedClient.registeredAddress}</p></div>
                </div>
              </div>

              {/* Services List */}
              <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm space-y-4">
                <h4 className="text-[10px] font-black text-indigo-600 uppercase tracking-widest flex items-center gap-2"><ListPlus size={14}/> Scope of Services</h4>
                <div className="flex flex-wrap gap-2">
                  {selectedClient.servicesNeeded.map((s, idx) => (
                    <span key={idx} className="px-3 py-1 bg-indigo-50 text-indigo-700 rounded-full text-xs font-bold border border-indigo-100">{s}</span>
                  ))}
                  {selectedClient.servicesNeeded.length === 0 && <p className="text-xs text-gray-400 italic">No specific services defined.</p>}
                </div>
              </div>

              {/* Personnel Sections */}
              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-indigo-600 uppercase tracking-widest flex items-center gap-2"><Users size={14}/> Key Personnel</h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                   <div className="bg-white p-5 rounded-3xl border border-gray-100">
                      <p className="text-[10px] font-black text-gray-400 uppercase mb-3">Directors ({selectedClient.directors.length})</p>
                      <ul className="space-y-2">
                         {selectedClient.directors.map((d, i) => <li key={i} className="text-xs font-bold text-gray-700 flex justify-between"><span>{d.name}</span> <span className="text-gray-400 text-[10px]">{d.nationality}</span></li>)}
                      </ul>
                   </div>
                   <div className="bg-white p-5 rounded-3xl border border-gray-100">
                      <p className="text-[10px] font-black text-gray-400 uppercase mb-3">Shareholders ({selectedClient.shareholders.length})</p>
                      <ul className="space-y-2">
                         {selectedClient.shareholders.map((s, i) => <li key={i} className="text-xs font-bold text-gray-700 flex justify-between"><span>{s.name} ({s.ownershipPercentage}%)</span> <span className="text-gray-400 text-[10px]">{s.type}</span></li>)}
                      </ul>
                   </div>
                </div>
              </div>
            </div>

            <div className="px-8 py-6 bg-gray-50 border-t border-gray-100 flex justify-between items-center">
               <div className="flex items-center gap-2">
                  <span className="text-xs text-gray-400 font-bold uppercase">Risk Profile:</span>
                  {getRiskBadge(selectedClient.riskLevel)}
               </div>
               <button onClick={() => setSelectedClient(null)} className="px-6 py-2.5 bg-slate-900 text-white rounded-xl font-bold hover:bg-slate-800 transition-all shadow-lg">Close Dossier</button>
            </div>
          </div>
        </div>
      )}

      {/* Onboarding Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md flex items-center justify-center z-50 p-4">
          <div className="bg-gray-50 rounded-[2.5rem] shadow-2xl w-full max-w-7xl max-h-[95vh] flex flex-col overflow-hidden animate-in fade-in zoom-in duration-300 border border-white/20">
            <div className="px-10 py-8 bg-indigo-600 text-white flex justify-between items-center shrink-0">
              <div className="flex items-center gap-5">
                <div className="bg-white/20 p-3.5 rounded-2xl"><ShieldCheck size={32}/></div>
                <div>
                  <h3 className="text-3xl font-black tracking-tight">Comprehensive Onboarding</h3>
                  <p className="text-xs text-indigo-100 font-bold uppercase tracking-[0.2em] opacity-80 mt-1">Full Database Synchronization Protocol v2.0</p>
                </div>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="text-white/60 hover:text-white p-3 rounded-full hover:bg-white/10 transition-all"><X size={28}/></button>
            </div>

            <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-10 space-y-10 custom-scrollbar">

              {/* Core Company Profile */}
              <FormSection title="Company Registry Profile" icon={<Landmark size={20}/>}>
                <InputField label="File Ref (No)" required value={formData.no} onChange={(v: string) => setFormData({...formData, no: v})} />
                <InputField label="Client Legal Name" required value={formData.firstName} onChange={(v: string) => setFormData({...formData, firstName: v})} />
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block">Status</label>
                  <select className="w-full border-gray-100 border-2 rounded-xl p-3 text-sm font-medium" value={formData.status} onChange={e => setFormData({...formData, status: e.target.value as any})}>
                    <option value="Pending">Pending</option>
                    <option value="Active">Active</option>
                    <option value="Closed">Closed</option>
                    <option value="Blacklisted">Blacklisted</option>
                  </select>
                </div>
                <InputField label="QFC Registration No" value={formData.qfcNo} onChange={(v: string) => setFormData({...formData, qfcNo: v})} />
                <InputField label="Legal Structure" placeholder="e.g. LLC, Branch" value={formData.legalStructure} onChange={(v: string) => setFormData({...formData, legalStructure: v})} />
                <InputField label="Company Nationality" required value={formData.corporateNationality} onChange={(v: string) => setFormData({...formData, corporateNationality: v})} />
                <InputField label="Company Type" value={formData.companyType} onChange={(v: string) => setFormData({...formData, companyType: v})} />
                <InputField label="Nature of Business" value={formData.natureOfBusiness} onChange={(v: string) => setFormData({...formData, natureOfBusiness: v})} />
                <InputField label="Approved Auditor" value={formData.approvedAuditor} onChange={(v: string) => setFormData({...formData, approvedAuditor: v})} />
              </FormSection>

              {/* Engagement & Milestones */}
              <FormSection title="Engagement & Timeline" icon={<Calendar size={20}/>}>
                <InputField label="Engagement Year" type="number" value={formData.engagementYear} onChange={(v: string) => setFormData({...formData, engagementYear: v})} />
                <InputField label="Engagement Date" type="date" value={formData.engagementDate} onChange={(v: string) => setFormData({...formData, engagementDate: v})} />
                <InputField label="Onboarding Date" type="date" value={formData.onboardingDate} onChange={(v: string) => setFormData({...formData, onboardingDate: v})} />
                <InputField label="Incorporation Date" type="date" value={formData.incorporationDate} onChange={(v: string) => setFormData({...formData, incorporationDate: v})} />
                <InputField label="CR Expiry Date" type="date" value={formData.crExpiryDate} onChange={(v: string) => setFormData({...formData, crExpiryDate: v})} />
                <InputField label="Entity Card No" value={formData.entityCardNo} onChange={(v: string) => setFormData({...formData, entityCardNo: v})} />
                <InputField label="Entity Card Expiry" type="date" value={formData.entityCardExpiry} onChange={(v: string) => setFormData({...formData, entityCardExpiry: v})} />
                <InputField label="License No" value={formData.license} onChange={(v: string) => setFormData({...formData, license: v})} />
                <InputField label="License Expiry" type="date" value={formData.licenseExpiry} onChange={(v: string) => setFormData({...formData, licenseExpiry: v})} />
              </FormSection>

              {/* Dynamic Services Section */}
              <div className="bg-white p-8 rounded-3xl border border-gray-100 shadow-sm space-y-6">
                <div className="flex items-center justify-between border-b border-indigo-50 pb-4">
                  <div className="flex items-center gap-3 text-indigo-700 font-black text-sm uppercase tracking-wider">
                    <ListPlus size={20}/>
                    <span>Services Needed / Provided</span>
                  </div>
                  <button type="button" onClick={() => addRow('servicesNeeded')} className="text-[10px] font-black text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-lg flex items-center gap-2 hover:bg-indigo-100">
                    <Plus size={14}/> Add Service
                  </button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {formData.servicesNeeded.map((service, idx) => (
                    <div key={idx} className="flex gap-2">
                      <input className="flex-1 border-gray-100 border-2 rounded-xl p-3 text-sm" value={service} onChange={(e) => updateRow('servicesNeeded', idx, '', e.target.value)} placeholder="Service description..." />
                      <button type="button" onClick={() => removeRow('servicesNeeded', idx)} className="p-3 text-red-400 hover:text-red-600"><Trash2 size={18}/></button>
                    </div>
                  ))}
                  {formData.servicesNeeded.length === 0 && <p className="text-xs text-gray-400 italic">No services listed</p>}
                </div>
              </div>

              {/* Personnel Multi-Entry Sections */}
              {[
                { id: 'directors', label: 'Directors', icon: <User size={20}/> },
                { id: 'shareholders', label: 'Shareholders', icon: <Percent size={20}/> },
                { id: 'ubos', label: 'Ultimate Beneficial Owners', icon: <Users size={20}/> },
                { id: 'signatories', label: 'Authorized Signatories', icon: <ShieldCheck size={20}/> }
              ].map((sec) => (
                <div key={sec.id} className="bg-white p-8 rounded-3xl border border-gray-100 shadow-sm space-y-6">
                  <div className="flex items-center justify-between border-b border-indigo-50 pb-4">
                    <div className="flex items-center gap-3 text-indigo-700 font-black text-sm uppercase tracking-wider">
                      {sec.icon}
                      <span>{sec.label}</span>
                    </div>
                    <button type="button" onClick={() => addRow(sec.id as any)} className="text-[10px] font-black text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-lg flex items-center gap-2 hover:bg-indigo-100">
                      <Plus size={14}/> Add Entry
                    </button>
                  </div>
                  <div className="space-y-4">
                    {(formData[sec.id as keyof typeof formData] as any[]).map((row, idx) => (
                      <div key={idx} className="grid grid-cols-1 md:grid-cols-5 gap-4 p-4 bg-gray-50 rounded-2xl border border-gray-100 relative">
                        <button type="button" onClick={() => removeRow(sec.id as any, idx)} className="absolute -top-2 -right-2 bg-red-100 text-red-600 p-1 rounded-full hover:bg-red-200"><X size={14}/></button>
                        <InputField label="Name" value={row.name} onChange={(v: any) => updateRow(sec.id as any, idx, 'name', v)} />
                        <InputField label="QID / Passport" value={row.qidOrPassport || row.qidPassportCrNo} onChange={(v: any) => updateRow(sec.id as any, idx, sec.id === 'shareholders' ? 'qidPassportCrNo' : 'qidOrPassport', v)} />
                        <InputField label="Nationality" value={row.nationality} onChange={(v: any) => updateRow(sec.id as any, idx, 'nationality', v)} />
                        <InputField label={sec.id === 'shareholders' ? "DOB / DOI" : "DOB"} type="date" value={row.dob || row.dobOrDoi} onChange={(v: any) => updateRow(sec.id as any, idx, sec.id === 'shareholders' ? 'dobOrDoi' : 'dob', v)} />
                        {sec.id === 'shareholders' && (
                          <InputField label="Ownership %" type="number" value={row.ownershipPercentage} onChange={(v: any) => updateRow(sec.id as any, idx, 'ownershipPercentage', parseFloat(v))} />
                        )}
                        {sec.id === 'signatories' && (
                          <InputField label="Authority" value={row.authority} onChange={(v: any) => updateRow(sec.id as any, idx, 'authority', v)} />
                        )}
                      </div>
