const PersonRecordList = ({ label, items, onChange }: { label: string, items: PersonRecord[], onChange: (items: PersonRecord[]) => void }) => {
  const addItem = () => {
    onChange([...items, { name: '', qid_passport: '', nationality: '', dob: '' }]);
  };
  const updateItem = (index: number, field: keyof PersonRecord, value: string) => {
    const newItems = [...items];
    newItems[index] = { ...newItems[index], [field]: value };
    onChange(newItems);
  };
  const removeItem = (index: number) => {
    onChange(items.filter((_, i) => i !== index));
  };

  return (
    <div className="md:col-span-3 space-y-3">
      <div className="flex justify-between items-center">
        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{label}</label>
        <button type="button" onClick={addItem} className="text-xs flex items-center gap-1 text-indigo-600 font-bold hover:underline">
          <UserPlus size={14} /> Add Record
        </button>
      </div>
      <div className="space-y-3">
        {items.map((item, idx) => (
          <div key={idx} className="grid grid-cols-1 md:grid-cols-5 gap-3 p-4 bg-gray-50 rounded-2xl relative">
            <InputField label="Name" value={item.name} onChange={(v: string) => updateItem(idx, 'name', v)} />
            <InputField label="QID/Passport" value={item.qid_passport} onChange={(v: string) => updateItem(idx, 'qid_passport', v)} />
            <InputField label="Nationality" value={item.nationality} onChange={(v: string) => updateItem(idx, 'nationality', v)} />
            <InputField label="DOB" type="date" value={item.dob} onChange={(v: string) => updateItem(idx, 'dob', v)} />
            <div className="flex items-end pb-1">
              <button type="button" onClick={() => removeItem(idx)} className="p-3 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all">
                <Trash2 size={18} />
              </button>
            </div>
          </div>
        ))}
        {items.length === 0 && <p className="text-center py-4 text-xs text-gray-300 italic border-2 border-dashed border-gray-50 rounded-2xl">No data provided</p>}
      </div>
    </div>
  );
};

