import { createClient } from '@supabase/supabase-js';
import { Client, AppSettings, RiskLevel } from '../types';

let supabase: any = null;

export const initSupabase = (settings: AppSettings) => {
  if (settings.supabaseUrl && settings.supabaseKey) {
    supabase = createClient(settings.supabaseUrl, settings.supabaseKey);
    return true;
  }
  return false;
};

export const checkConnection = async () => {
  if (!supabase) return false;
  try {
    const { error } = await supabase.from('clients').select('id').limit(1);
    return !error;
  } catch {
    return false;
  }
};

export const fetchCloudClients = async (): Promise<Client[] | null> => {
  if (!supabase) return null;
  const { data, error } = await supabase.from('clients').select('*').order('created_at', { ascending: false });
  if (error) throw error;
  return data;
};

export const upsertCloudClient = async (client: Client) => {
  if (!supabase) return;
  // Use upsert to handle both new records and updates to existing ones
  const { error } = await supabase.from('clients').upsert([client], { onConflict: 'id' });
  if (error) throw error;
};

export const deleteCloudClient = async (id: string) => {
  if (!supabase) return;
  const { error } = await supabase.from('clients').delete().eq('id', id);
  if (error) throw error;
};

export const subscribeToClients = (onUpdate: () => void) => {
  if (!supabase) return null;
  return supabase.channel('clients-changes').on('postgres_changes', { event: '*', schema: 'public', table: 'clients' }, onUpdate).subscribe();
};

export const unsubscribeFromClients = async (channel: any) => {
  if (supabase && channel) await supabase.removeChannel(channel);
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { ShieldCheck } from 'lucide-react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import ClientManager from './components/ClientManager';
import SanctionsBrowser from './components/SanctionsBrowser';
import AdminPanel from './components/AdminPanel';
import { Client, SanctionEntry, SystemLog, RiskLevel, EntityType, AppSettings, UserRole, KYCStatus } from './types';
import { generateMockSanctions, QATAR_MOCK_SANCTIONS } from './services/mockData';
import { screenClient } from './services/screeningEngine';
import { OFFICIAL_UN_XML_URL, parseUNSanctionsXML, parseCSVToSanctions } from './services/unSanctionsService';
import { initSupabase, fetchCloudClients, upsertCloudClient, deleteCloudClient, subscribeToClients, unsubscribeFromClients, checkConnection } from './services/cloudDb';

const DEFAULT_SETTINGS: AppSettings = {
  autoSync: true,
  syncIntervalMinutes: 1440,
  sourceUrl: OFFICIAL_UN_XML_URL,
  lastSync: 'Never',
  nextSync: new Date(Date.now() + 86400000).toISOString()
};

const App: React.FC = () => {
  const [clients, setClients] = useState<Client[]>([]);
  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [logs, setLogs] = useState<SystemLog[]>([]);
  const [settings, setSettings] = useState<AppSettings>(() => {
    const stored = localStorage.getItem('unsg_settings');
    return stored ? JSON.parse(stored) : DEFAULT_SETTINGS;
  });
  const [isUpdating, setIsUpdating] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<'LOCAL' | 'CONNECTING' | 'CONNECTED' | 'ERROR'>('LOCAL');
  const [cloudError, setCloudError] = useState<string | null>(null);

  // Simulated Authentication Context - Set via Admin for testing
  const [currentUserRole, setCurrentUserRole] = useState<UserRole>(UserRole.ADMIN);
  const [currentUserId, setCurrentUserId] = useState<string>("USR-9921-DEMO"); 

  const subscriptionRef = useRef<any>(null);

  const addLog = useCallback((action: string, details: string, status: 'SUCCESS' | 'FAILURE' | 'WARNING') => {
    const newLog: SystemLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toISOString(),
      action,
      details,
      status
    };
    setLogs(prev => [...prev, newLog]);
  }, []);

  const refreshClients = useCallback(async (isConnected: boolean) => {
    if (isConnected) {
      try {
        const cloudClients = await fetchCloudClients();
        if (cloudClients) {
          setClients(cloudClients);
          setCloudError(null);
          addLog('CLOUD_SYNC', `Synced ${cloudClients.length} clients from cloud.`, 'SUCCESS');
        }
      } catch (err: any) {
        setCloudError(`Cloud Fetch Error: ${err.message}`);
        addLog('CLOUD_ERROR', `Cloud fetch failed.`, 'FAILURE');
      }
    } else {
      const stored = localStorage.getItem('unsg_clients');
      if (stored) setClients(JSON.parse(stored));
      else setClients([]);
    }
  }, [addLog]);

  useEffect(() => {
    const connectToCloud = async () => {
      if (!settings.supabaseUrl || !settings.supabaseKey) {
        setConnectionStatus('LOCAL');
        refreshClients(false);
        return;
      }
      setConnectionStatus('CONNECTING');
      const initialized = initSupabase(settings);
      if (initialized) {
        const healthy = await checkConnection();
        if (healthy) {
          setConnectionStatus('CONNECTED');
          await refreshClients(true);
          if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
          subscriptionRef.current = subscribeToClients(() => refreshClients(true));
        } else {
          setConnectionStatus('ERROR');
          setCloudError("Table missing or unauthorized.");
          refreshClients(false);
        }
      } else {
        setConnectionStatus('ERROR');
        refreshClients(false);
      }
    };
    connectToCloud();
    localStorage.setItem('unsg_settings', JSON.stringify(settings));
    return () => { if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current); };
  }, [settings, refreshClients]);

  useEffect(() => {
    const storedSanctions = localStorage.getItem('unsg_sanctions');
    if (storedSanctions) setSanctions(JSON.parse(storedSanctions));
    else setSanctions([...generateMockSanctions(10), ...QATAR_MOCK_SANCTIONS]);
  }, []);

  const handleAddClient = async (newClient: Client) => {
    if (connectionStatus === 'CONNECTED') {
      try { 
        await upsertCloudClient(newClient); 
        await refreshClients(true);
        addLog('KYC_DRAFT_CREATED', `Entity ${newClient["Client Name"]} saved as Draft by ${currentUserId}.`, 'SUCCESS');
      } catch (e: any) { 
        addLog('CLOUD_ERROR', e.message, 'FAILURE'); 
      }
    } else {
      setClients(prev => [newClient, ...prev]);
      localStorage.setItem('unsg_clients', JSON.stringify([newClient, ...clients]));
    }
  };

  const handleUpdateClient = async (updatedClient: Client) => {
    addLog('KYC_STATUS_UPDATE', `Entity ${updatedClient["Client Name"]} moved to ${updatedClient.kyc_status} by ${currentUserId}.`, 'SUCCESS');

    if (connectionStatus === 'CONNECTED') {
      try {
        await upsertCloudClient(updatedClient);
        await refreshClients(true);
      } catch (e: any) {
        addLog('CLOUD_ERROR', e.message, 'FAILURE');
      }
    } else {
      const newClients = clients.map(c => c.id === updatedClient.id ? updatedClient : c);
      setClients(newClients);
      localStorage.setItem('unsg_clients', JSON.stringify(newClients));
    }
  };

  const handleSimulationSwitch = (role: UserRole, id: string) => {
    setCurrentUserRole(role);
    setCurrentUserId(id);
    addLog('USER_SWITCH', `Simulating session for ${id} (${role})`, 'SUCCESS');
  };

  return (
    <Router>
      <Layout cloudError={cloudError} isCloudConnected={connectionStatus === 'CONNECTED'} isConnecting={connectionStatus === 'CONNECTING'}>
        <Routes>
          <Route path="/" element={<Dashboard clients={clients} sanctionsCount={sanctions.length} />} />
          <Route path="/clients" element={<ClientManager 
              clients={clients} 
              onAddClient={handleAddClient} 
              onUpdateClient={handleUpdateClient}
              onDeleteClient={async id => { if (connectionStatus === 'CONNECTED') await deleteCloudClient(id).then(() => refreshClients(true)).catch(e => addLog('CLOUD_ERROR', e.message, 'FAILURE')); else setClients(prev => prev.filter(c => c.id !== id)); }} 
              onRefresh={() => refreshClients(connectionStatus === 'CONNECTED')} 
              currentUserRole={currentUserRole}
              currentUserId={currentUserId}
            />} />
          <Route path="/sanctions" element={<SanctionsBrowser sanctions={sanctions} lastUpdated={settings.lastSync} onRefresh={() => {}} isUpdating={isUpdating} onFileUpload={() => {}} />} />
          <Route path="/admin" element={<AdminPanel 
            logs={logs} 
            settings={settings} 
            onUpdateSettings={setSettings} 
            onSwitchUser={handleSimulationSwitch}
            currentUserId={currentUserId}
          />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </Router>
  );
};

