interface PasswordUpdateProps {
  user: UserProfile;
  onUpdate: (newPassword: string) => void;
}

const PasswordUpdate: React.FC<PasswordUpdateProps> = ({ user, onUpdate }) => {
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');

  const requirements = [
    { label: 'Min 8 characters', met: password.length >= 8 },
    { label: 'Lowercase letter', met: /[a-z]/.test(password) },
    { label: 'Uppercase letter', met: /[A-Z]/.test(password) },
    { label: 'Special character', met: /[^A-Za-z0-9]/.test(password) },
    { label: 'At least one number', met: /[0-9]/.test(password) },
    { label: 'Passwords match', met: password !== '' && password === confirm }
  ];

  const isValid = requirements.every(r => r.met);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
