          <p className="text-indigo-100 text-sm mt-2 opacity-80 uppercase tracking-widest font-bold">Action Required</p>
        </div>

        <div className="p-8">
          <div className="bg-amber-50 border border-amber-100 rounded-2xl p-4 mb-8 flex gap-3 text-amber-800">
