import React, { useState, useEffect, useCallback, useRef } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import ClientManager from './components/ClientManager';
import SanctionsBrowser from './components/SanctionsBrowser';
import AdminPanel from './components/AdminPanel';
import Login from './components/Login';
import PasswordUpdate from './components/PasswordUpdate';
import { Client, SanctionEntry, SystemLog, RiskLevel, AppSettings, UserRole, UserProfile, AccountStatus } from './types';
import { generateMockSanctions, QATAR_MOCK_SANCTIONS } from './services/mockData';
import { OFFICIAL_UN_XML_URL } from './services/unSanctionsService';
import { initSupabase, fetchCloudClients, upsertCloudClient, deleteCloudClient, subscribeToClients, unsubscribeFromClients, checkConnection } from './services/cloudDb';

const DEFAULT_SETTINGS: AppSettings = {
  autoSync: true,
  syncIntervalMinutes: 1440,
  sourceUrl: OFFICIAL_UN_XML_URL,
  lastSync: 'Never',
  nextSync: new Date(Date.now() + 86400000).toISOString()
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(() => {
    const saved = localStorage.getItem('unsg_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [clients, setClients] = useState<Client[]>([]);
  const [sanctions, setSanctions] = useState<SanctionEntry[]>([]);
  const [logs, setLogs] = useState<SystemLog[]>([]);
  const [settings, setSettings] = useState<AppSettings>(() => {
    const stored = localStorage.getItem('unsg_settings');
    return stored ? JSON.parse(stored) : DEFAULT_SETTINGS;
  });
  const [connectionStatus, setConnectionStatus] = useState<'LOCAL' | 'CONNECTING' | 'CONNECTED' | 'ERROR'>('LOCAL');
  const [cloudError, setCloudError] = useState<string | null>(null);

  const subscriptionRef = useRef<any>(null);

  // Initialize DB with requested users if missing
  useEffect(() => {
    const storedUsersStr = localStorage.getItem('unsg_users');
    let users = storedUsersStr ? JSON.parse(storedUsersStr) : [];

    const targetEmail = 'reham.tanany@rodlme.com';
    const hasTarget = users.some((u: any) => u.email.toLowerCase() === targetEmail);

    if (!hasTarget) {
      const newUser = {
        id: 'USR-REHAM-001',
        email: targetEmail,
        password: 'ChangeMe@2026',
        full_name: 'Reham Tanany',
        role: UserRole.DATA_ENTRY,
        is_system_admin: false,
        status: AccountStatus.ACTIVE,
        must_change_password: true,
        password_expiry: new Date(Date.now() + 80 * 86400000).toISOString(),
        created_at: new Date().toISOString()
      };
      users.push(newUser);
      localStorage.setItem('unsg_users', JSON.stringify(users));
      console.log("System: Provisioned requested user reham.tanany@rodlme.com into local DB.");
    }
  }, []);

  const addLog = useCallback((action: string, details: string, status: 'SUCCESS' | 'FAILURE' | 'WARNING') => {
    const newLog: SystemLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toISOString(),
      action,
      details,
      status,
      user_id: currentUser?.id
    };
    setLogs(prev => [...prev, newLog]);
  }, [currentUser]);

  const handleLogin = (user: UserProfile) => {
    setCurrentUser(user);
    localStorage.setItem('unsg_session', JSON.stringify(user));
    addLog('AUTH_LOGIN', `User ${user.email} successfully authenticated.`, 'SUCCESS');
  };

  const handleLogout = () => {
    addLog('AUTH_LOGOUT', `User ${currentUser?.email} session terminated.`, 'SUCCESS');
    setCurrentUser(null);
    localStorage.removeItem('unsg_session');
  };

  const handlePasswordUpdate = (newPassword: string) => {
    if (!currentUser) return;
    const updated = { ...currentUser, must_change_password: false };

    // Also update the password in the "DB"
    const storedUsers = JSON.parse(localStorage.getItem('unsg_users') || '[]');
    const updatedUsers = storedUsers.map((u: any) => 
      u.email.toLowerCase() === currentUser.email.toLowerCase() ? { ...u, password: newPassword, must_change_password: false } : u
    );
    localStorage.setItem('unsg_users', JSON.stringify(updatedUsers));

    setCurrentUser(updated);
    localStorage.setItem('unsg_session', JSON.stringify(updated));
    addLog('SECURITY_PASSWORD_CHANGE', `Mandatory password policy successfully satisfied.`, 'SUCCESS');
  };

  const refreshClients = useCallback(async (isConnected: boolean) => {
    if (isConnected) {
      try {
        const cloudClients = await fetchCloudClients();
        if (cloudClients) {
          setClients(cloudClients);
          setCloudError(null);
        }
      } catch (err: any) {
        setCloudError(`Cloud Sync Interrupted: ${err.message}`);
      }
    } else {
      const stored = localStorage.getItem('unsg_clients');
      if (stored) setClients(JSON.parse(stored));
    }
  }, []);

  useEffect(() => {
    if (!currentUser) return;

    const connectToCloud = async () => {
      if (!settings.supabaseUrl || !settings.supabaseKey) {
        setConnectionStatus('LOCAL');
        refreshClients(false);
        return;
      }
      setConnectionStatus('CONNECTING');
      const initialized = initSupabase(settings);
      if (initialized) {
        const healthy = await checkConnection();
        if (healthy) {
          setConnectionStatus('CONNECTED');
          await refreshClients(true);
          if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current);
          subscriptionRef.current = subscribeToClients(() => refreshClients(true));
        } else {
          setConnectionStatus('ERROR');
          refreshClients(false);
        }
      } else {
        setConnectionStatus('ERROR');
        refreshClients(false);
      }
    };
    connectToCloud();
    return () => { if (subscriptionRef.current) unsubscribeFromClients(subscriptionRef.current); };
  }, [settings, refreshClients, currentUser]);

  useEffect(() => {
    const storedSanctions = localStorage.getItem('unsg_sanctions');
    if (storedSanctions) setSanctions(JSON.parse(storedSanctions));
    else setSanctions([...generateMockSanctions(10), ...QATAR_MOCK_SANCTIONS]);
  }, []);

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  if (currentUser.must_change_password) {
    return <PasswordUpdate user={currentUser} onUpdate={handlePasswordUpdate} />;
  }

  return (
    <Router>
      <Layout 
        cloudError={cloudError} 
        isCloudConnected={connectionStatus === 'CONNECTED'} 
        isConnecting={connectionStatus === 'CONNECTING'}
        onLogout={handleLogout}
        currentUser={currentUser}
      >
        <Routes>
          <Route path="/" element={<Dashboard clients={clients} sanctionsCount={sanctions.length} />} />
          <Route path="/clients" element={<ClientManager 
              clients={clients} 
              onAddClient={async (newClient) => {
                if (connectionStatus === 'CONNECTED') await upsertCloudClient(newClient);
                else setClients(prev => [newClient, ...prev]);
                addLog('KYC_ADD', `New entity ${newClient["Client Name"]} onboarded.`, 'SUCCESS');
              }} 
              onUpdateClient={async (updated) => {
                if (connectionStatus === 'CONNECTED') await upsertCloudClient(updated);
                setClients(prev => prev.map(c => c.id === updated.id ? updated : c));
                addLog('KYC_STATUS_CHANGE', `Entity status updated to ${updated.kyc_status}.`, 'SUCCESS');
              }}
              onDeleteClient={async (id) => {
                if (connectionStatus === 'CONNECTED') await deleteCloudClient(id);
                setClients(prev => prev.filter(c => c.id !== id));
              }}
              onRefresh={() => refreshClients(connectionStatus === 'CONNECTED')} 
              currentUserRole={currentUser.role}
              currentUserId={currentUser.id}
            />} />
          <Route path="/sanctions" element={<SanctionsBrowser sanctions={sanctions} lastUpdated={settings.lastSync} onRefresh={() => {}} isUpdating={false} onFileUpload={() => {}} />} />
          <Route path="/admin" element={
            currentUser.is_system_admin || currentUser.role === UserRole.ADMIN ? (
              <AdminPanel 
                logs={logs} 
                settings={settings} 
                onUpdateSettings={setSettings} 
                currentUserId={currentUser.id}
                currentUser={currentUser}
              />
            ) : <Navigate to="/" replace />
          } />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </Router>
  );
};

export default App;

