import { createClient } from '@supabase/supabase-js';
import { Client, AppSettings, RiskLevel, UserProfile } from '../types';

let supabase: any = null;

export const initSupabase = (settings: AppSettings) => {
  if (settings.supabaseUrl && settings.supabaseKey) {
    supabase = createClient(settings.supabaseUrl, settings.supabaseKey);
    return true;
  }
  return false;
};

export const checkConnection = async () => {
  if (!supabase) return false;
  try {
    const { error } = await supabase.from('clients').select('id').limit(1);
    return !error;
  } catch {
    return false;
  }
};

// --- CLIENT OPERATIONS ---

export const fetchCloudClients = async (): Promise<Client[] | null> => {
  if (!supabase) return null;
  const { data, error } = await supabase.from('clients').select('*').order('created_at', { ascending: false });
  if (error) throw error;
  return data;
};

export const upsertCloudClient = async (client: Client) => {
  if (!supabase) return;
  const { error } = await supabase.from('clients').upsert([client], { onConflict: 'id' });
  if (error) throw error;
};

export const deleteCloudClient = async (id: string) => {
  if (!supabase) return;
  const { error } = await supabase.from('clients').delete().eq('id', id);
  if (error) throw error;
};

// --- USER PROFILE OPERATIONS ---

export const fetchCloudUsers = async (): Promise<UserProfile[] | null> => {
  if (!supabase) return null;
  try {
    const { data, error } = await supabase.from('profiles').select('*');
    if (error) {
      console.warn("Profiles table might not exist yet. Using local mode.");
      return null;
    }
    return data;
  } catch (err) {
    return null;
  }
};

export const upsertCloudUser = async (user: any) => {
  if (!supabase) return;
  // Map App User to DB Profile
  const dbProfile = {
    id: user.id,
    email: user.email.toLowerCase(),
    full_name: user.full_name,
    role_id: user.role,
    status: user.status,
    is_system_admin: user.is_system_admin || false,
    must_change_password: user.must_change_password,
    password_expiry: user.password_expiry,
    password_hash_mock: user.password // In a real app, this would be handled by Auth, but for this project we store it in profiles
  };

  const { error } = await supabase.from('profiles').upsert([dbProfile], { onConflict: 'email' });
  if (error) console.error("Cloud Sync Error (Users):", error.message);
};

export const deleteCloudUser = async (email: string) => {
  if (!supabase) return;
  const { error } = await supabase.from('profiles').delete().eq('email', email.toLowerCase());
  if (error) console.error("Cloud Delete Error:", error.message);
};

export const subscribeToClients = (onUpdate: () => void) => {
  if (!supabase) return null;
  return supabase.channel('clients-changes').on('postgres_changes', { event: '*', schema: 'public', table: 'clients' }, onUpdate).subscribe();
};

export const unsubscribeFromClients = async (channel: any) => {
  if (supabase && channel) await supabase.removeChannel(channel);
};

import React, { useState, useEffect } from 'react';
import { AppSettings, SystemLog, UserRole, UserProfile, AccountStatus } from '../types';
import { Save, Cloud, Terminal, Check, Copy, AlertTriangle, ShieldCheck, History, Users, Lock, UserCircle, ShieldAlert, Plus, Power, Key, X, Mail, UserPlus, CheckCircle2, Trash2, UserMinus, AlertCircle, RefreshCw, CloudCheck } from 'lucide-react';
import { upsertCloudUser, deleteCloudUser } from '../services/cloudDb';

interface AdminPanelProps {
  settings: AppSettings;
  logs: SystemLog[];
  onUpdateSettings: (newSettings: AppSettings) => void;
  onSwitchUser?: (role: UserRole, id: string) => void;
  currentUserId?: string;
  currentUser?: UserProfile | null;
}

const DEFAULT_TEMP_PASSWORD = 'ChangeMe@2026';

const AdminPanel: React.FC<AdminPanelProps> = ({ settings, logs, onUpdateSettings, onSwitchUser, currentUserId, currentUser }) => {
  const [localSettings, setLocalSettings] = useState<AppSettings>(settings);
  const [activeTab, setActiveTab] = useState<'config' | 'rbac' | 'logs' | 'users'>('users');
  const [systemUsers, setSystemUsers] = useState<any[]>(() => JSON.parse(localStorage.getItem('unsg_users') || '[]'));
  const [isSyncing, setIsSyncing] = useState(false);

  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [newUserEmail, setNewUserEmail] = useState('');
  const [newUserName, setNewUserName] = useState('');
  const [newUserRole, setNewUserRole] = useState<UserRole>(UserRole.DATA_ENTRY);
  const [pendingDelete, setPendingDelete] = useState<string | null>(null);
  const [createdUser, setCreatedUser] = useState<{name: string, email: string} | null>(null);

  useEffect(() => { setLocalSettings(settings); }, [settings]);

  const saveUsersToStorage = async (users: any[]) => {
    setSystemUsers(users);
    localStorage.setItem('unsg_users', JSON.stringify(users));
  };

  const handleCloudSync = async (user: any, isDelete: boolean = false) => {
    if (!settings.supabaseUrl) return;
    setIsSyncing(true);
    try {
      if (isDelete) await deleteCloudUser(user.email);
      else await upsertCloudUser(user);
    } catch (e) {
      console.error("Sync Failed", e);
    } finally {
      setIsSyncing(false);
    }
  };

  const toggleUserStatus = async (email: string) => {
    const updated = systemUsers.map(u => {
      if (u.email === email) {
        const newUser = { ...u, status: u.status === AccountStatus.ACTIVE ? AccountStatus.DISABLED : AccountStatus.ACTIVE };
        handleCloudSync(newUser);
        return newUser;
      }
      return u;
    });
    saveUsersToStorage(updated);
  };

  const resetUserPassword = async (email: string) => {
    if (!window.confirm(`Reset password for ${email}?`)) return;
    const updated = systemUsers.map(u => {
      if (u.email === email) {
        const newUser = { 
          ...u, 
          password: DEFAULT_TEMP_PASSWORD, 
          must_change_password: true,
          password_expiry: new Date(Date.now() + 80 * 86400000).toISOString()
        };
        handleCloudSync(newUser);
        return newUser;
      }
      return u;
    });
    saveUsersToStorage(updated);
    alert(`Reset to: ${DEFAULT_TEMP_PASSWORD}`);
  };

  const deleteUser = async (email: string) => {
    const updated = systemUsers.filter(u => u.email !== email);
    await handleCloudSync({ email }, true);
    saveUsersToStorage(updated);
    setPendingDelete(null);
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUserEmail || !newUserName) return;
    const normalizedEmail = newUserEmail.trim().toLowerCase();

    if (systemUsers.some(u => u.email === normalizedEmail) || normalizedEmail === 'aqandeel@gmail.com') {
      alert("Email already registered.");
      return;
    }

    const newUser = {
      id: `USR-${Math.random().toString(36).substr(2, 5).toUpperCase()}`,
      email: normalizedEmail,
      password: DEFAULT_TEMP_PASSWORD,
      full_name: newUserName,
      role: newUserRole,
      is_system_admin: false,
      status: AccountStatus.ACTIVE,
      must_change_password: true,
      password_expiry: new Date(Date.now() + 80 * 86400000).toISOString(),
      created_at: new Date().toISOString()
    };

    const newList = [...systemUsers, newUser];
    await handleCloudSync(newUser);
    saveUsersToStorage(newList);
    setCreatedUser({ name: newUserName, email: normalizedEmail });
    setNewUserEmail(''); setNewUserName(''); setIsUserModalOpen(false);
  };

  const isSystemAdmin = currentUser?.is_system_admin;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
          <div className="bg-indigo-600 p-3 rounded-2xl text-white shadow-lg">
            <ShieldCheck size={24}/>
          </div>
          <div>
            <h2 className="text-xl font-bold text-slate-900">Administrative Center</h2>
            <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-0.5">Role-Based Access Control System</p>
          </div>
        </div>
        <div className="flex gap-2">
            {isSystemAdmin && (
              <button onClick={() => setActiveTab('users')} className={`px-5 py-2.5 rounded-xl text-xs font-black transition-all uppercase tracking-tight ${activeTab === 'users' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}>Identities</button>
            )}
            <button onClick={() => setActiveTab('rbac')} className={`px-5 py-2.5 rounded-xl text-xs font-black transition-all uppercase tracking-tight ${activeTab === 'rbac' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}>Matrix</button>
            <button onClick={() => setActiveTab('logs')} className={`px-5 py-2.5 rounded-xl text-xs font-black transition-all uppercase tracking-tight ${activeTab === 'logs' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}>Audit</button>
        </div>
      </div>

      {activeTab === 'users' && isSystemAdmin && (
        <div className="space-y-6">
          {createdUser && (
            <div className="bg-emerald-50 border border-emerald-100 p-6 rounded-[2rem] flex items-start gap-5 animate-in fade-in slide-in-from-top-4">
              <div className="bg-emerald-500 text-white p-3 rounded-2xl shadow-lg shadow-emerald-100">
                <CheckCircle2 size={24}/>
              </div>
              <div className="flex-1">
                <h4 className="font-bold text-emerald-900 text-lg">Identity Synchronized</h4>
                <p className="text-sm text-emerald-700 mt-1"><strong>{createdUser.name}</strong> has been added to the cloud profiles table.</p>
                <div className="mt-4 flex flex-wrap gap-3">
                  <div className="bg-white px-4 py-3 rounded-2xl border border-emerald-100 flex items-center gap-4 shadow-sm">
                    <div>
                      <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Login ID</p>
                      <p className="text-sm font-mono font-bold text-slate-700">{createdUser.email}</p>
                    </div>
                  </div>
                  <div className="bg-white px-4 py-3 rounded-2xl border border-emerald-100 flex items-center gap-4 shadow-sm">
                    <div>
                      <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Initial Key</p>
                      <p className="text-sm font-mono font-bold text-indigo-600">{DEFAULT_TEMP_PASSWORD}</p>
                    </div>
                  </div>
                </div>
              </div>
              <button onClick={() => setCreatedUser(null)} className="text-emerald-300 hover:text-emerald-500 transition-colors"><X size={24}/></button>
            </div>
          )}

          <div className="flex justify-between items-center px-2">
            <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
               User Registry {isSyncing && <RefreshCw size={14} className="animate-spin text-indigo-500" />}
            </h3>
            <button onClick={() => setIsUserModalOpen(true)} className="bg-indigo-600 text-white px-6 py-3 rounded-2xl font-black text-xs flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100 group">
              <Plus size={18} className="group-hover:rotate-90 transition-transform" /> Provision Identity
            </button>
          </div>

          <div className="bg-white rounded-[2rem] border border-slate-100 overflow-hidden shadow-sm">
            <table className="w-full text-left">
              <thead className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-[0.1em] border-b">
                <tr>
                  <th className="px-8 py-5">Full Identity</th>
                  <th className="px-8 py-5">Sync State</th>
                  <th className="px-8 py-5">Role Policy</th>
                  <th className="px-8 py-5 text-right">Security Control</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                <tr className="bg-indigo-50/5">
                  <td className="px-8 py-5">
                    <div className="font-bold text-slate-900 text-sm">System Principal</div>
                    <div className="text-xs text-slate-400 font-medium">aqandeel@gmail.com</div>
                  </td>
                  <td className="px-8 py-5">
                    <span className="flex items-center gap-1.5 text-[10px] font-black text-indigo-500 uppercase">
                      <CloudCheck size={14} /> PERSISTENT
                    </span>
                  </td>
                  <td className="px-8 py-5">
                    <span className="px-3 py-1 bg-slate-900 text-white text-[10px] font-black rounded-lg uppercase">Root Admin</span>
                  </td>
                  <td className="px-8 py-5 text-right font-black text-[10px] text-slate-300 italic">SYSTEM_LOCK</td>
                </tr>
                {systemUsers.map(user => (
                  <tr key={user.email} className="hover:bg-slate-50/80 transition-all group">
                    <td className="px-8 py-5">
                      <div className="font-bold text-slate-900 text-sm">{user.full_name}</div>
                      <div className="text-xs text-slate-400 font-medium">{user.email}</div>
                    </td>
                    <td className="px-8 py-5">
                      <span className="flex items-center gap-1.5 text-[10px] font-black text-emerald-500 uppercase">
                        <CloudCheck size={14} /> CLOUD_SYNC
                      </span>
                    </td>
                    <td className="px-8 py-5">
                      <span className="px-3 py-1 bg-indigo-50 text-indigo-700 text-[10px] font-black rounded-lg border border-indigo-100 uppercase">
                        {user.role}
                      </span>
                    </td>
                    <td className="px-8 py-5 text-right">
                      {pendingDelete === user.email ? (
                        <div className="flex justify-end items-center gap-3">
                           <span className="text-[10px] font-black text-red-600 uppercase">Confirm Purge?</span>
                           <button onClick={() => deleteUser(user.email)} className="bg-red-600 text-white px-4 py-2 rounded-xl text-[10px] font-bold shadow-lg shadow-red-100">PURGE</button>
                           <button onClick={() => setPendingDelete(null)} className="bg-slate-100 text-slate-500 px-4 py-2 rounded-xl text-[10px] font-bold">ABORT</button>
                        </div>
                      ) : (
                        <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-all scale-95 group-hover:scale-100">
                          <button onClick={() => resetUserPassword(user.email)} className="p-2.5 text-slate-400 hover:bg-indigo-50 hover:text-indigo-600 rounded-xl transition-all" title="Reset Credentials">
                             <Key size={18}/>
                          </button>
                          <button onClick={() => toggleUserStatus(user.email)} className={`p-2.5 rounded-xl transition-all ${user.status === AccountStatus.ACTIVE ? 'text-amber-500 hover:bg-amber-50' : 'text-green-500 hover:bg-green-50'}`} title="Suspend Access">
                             <Power size={18}/>
                          </button>
                          <button onClick={() => setPendingDelete(user.email)} className="p-2.5 text-red-500 hover:bg-red-50 rounded-xl transition-all" title="Delete Identity">
                             <Trash2 size={18}/>
                          </button>
                        </div>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {isUserModalOpen && (
        <div className="fixed inset-0 bg-slate-950/70 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
