              <h3 className="text-2xl font-black">Identity Provisioning</h3>
              <p className="text-xs text-indigo-200 mt-1 uppercase tracking-widest font-bold">Regulatory ID Creation</p>
              <button onClick={() => setIsUserModalOpen(false)} className="absolute top-8 right-8 bg-white/10 p-2 rounded-full hover:bg-white/20 transition-all"><X size={20}/></button>
