import React, { useState } from 'react';
import { ShieldCheck, Lock, Mail, AlertCircle, Loader2, Eye, EyeOff, CheckCircle, RefreshCw } from 'lucide-react';
import { UserProfile, UserRole, AccountStatus } from '../types';
import { fetchCloudUsers } from '../services/cloudDb';

interface LoginProps {
  onLogin: (user: UserProfile) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    const normalizedEmail = email.trim().toLowerCase();
    const normalizedPassword = password.trim();

    // 1. Initial Root Admin Check
    const adminEmail = 'aqandeel@gmail.com';
    const adminPass = 'Rodl@2026';

    if (normalizedEmail === adminEmail && normalizedPassword === adminPass) {
      setIsSuccess(true);
      setTimeout(() => {
        onLogin({
          id: 'SYS-ADMIN-001',
          email: adminEmail,
          full_name: 'System Administrator',
          role: UserRole.ADMIN,
          is_system_admin: true,
          status: AccountStatus.ACTIVE,
          must_change_password: false,
          password_expiry: new Date(Date.now() + 80 * 86400000).toISOString(),
          created_at: new Date().toISOString()
        });
      }, 600);
      return;
    } 

    // 2. Check Local Storage Cache
    const storedUsers = JSON.parse(localStorage.getItem('unsg_users') || '[]');
    let user = storedUsers.find((u: any) => 
      u.email.trim().toLowerCase() === normalizedEmail && u.password.trim() === normalizedPassword
    );

    // 3. Fallback: Query Cloud Database for real-time validation
    if (!user) {
      try {
        const cloudUsers = await fetchCloudUsers();
        if (cloudUsers) {
          // In the mock cloud profiles, passwords would be stored or managed by Supabase Auth
          // Here we look for the profile matching the email
          const cloudMatch: any = cloudUsers.find((u: any) => u.email.toLowerCase() === normalizedEmail);

          // Match password (simulating credential verification)
          if (cloudMatch && cloudMatch.password_hash_mock === normalizedPassword) {
             user = {
               ...cloudMatch,
               role: cloudMatch.role_id,
               password: cloudMatch.password_hash_mock
             };
             // Cache user locally for next time
             const newLocalUsers = [...storedUsers.filter((u: any) => u.email !== normalizedEmail), user];
             localStorage.setItem('unsg_users', JSON.stringify(newLocalUsers));
          }
        }
      } catch (err) {
        console.error("Cloud Auth Error", err);
      }
    }

    if (user) {
      if (user.status === AccountStatus.DISABLED) {
        setError('Security Policy Alert: This account has been disabled by the Compliance Manager.');
        setIsLoading(false);
      } else {
        setIsSuccess(true);
        setTimeout(() => onLogin(user), 600);
      }
    } else {
      setError('Invalid identity credentials. Please verify your system email and access key.');
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4 relative overflow-hidden">
      <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none">
        <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-indigo-600 rounded-full blur-[120px]" />
        <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-blue-600 rounded-full blur-[120px]" />
      </div>

      <div className="w-full max-w-md relative z-10">
        <div className="bg-white rounded-[3rem] shadow-2xl overflow-hidden border border-white/10">
          <div className="p-10 md:p-14">
            <div className="flex flex-col items-center mb-12">
              <div className="bg-indigo-600 p-5 rounded-3xl shadow-2xl shadow-indigo-200 mb-8 transition-all hover:scale-110 duration-500">
                <ShieldCheck size={48} className="text-white" />
              </div>
              <h1 className="text-4xl font-black text-slate-900 tracking-tight">SanctionGuard</h1>
              <p className="text-slate-400 text-xs mt-3 font-black uppercase tracking-widest">Global Compliance Terminal</p>
            </div>

            {error && (
              <div className="mb-8 p-5 bg-red-50 border border-red-100 rounded-[1.5rem] flex items-start gap-4 text-red-600 text-xs leading-relaxed animate-in fade-in slide-in-from-top-2">
                <AlertCircle size={18} className="shrink-0 mt-0.5" />
                <p className="font-bold">{error}</p>
              </div>
            )}

            {isSuccess ? (
              <div className="flex flex-col items-center justify-center py-10 animate-in zoom-in-95 duration-300">
                <div className="h-20 w-20 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mb-6 shadow-xl shadow-emerald-50">
                  <CheckCircle size={40} />
                </div>
                <h3 className="text-2xl font-black text-slate-900">Access Granted</h3>
                <p className="text-slate-400 text-sm mt-2 font-medium">Provisioning secure session...</p>
              </div>
            ) : (
              <form onSubmit={handleLogin} className="space-y-7">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Email Identity</label>
                  <div className="relative">
                    <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input type="email" required className="w-full bg-slate-50 border-2 border-transparent focus:border-indigo-600 focus:bg-white rounded-[1.5rem] py-4.5 pl-14 pr-5 outline-none transition-all font-bold text-slate-700" placeholder="ola.alhmoud@rpmefirm.com" value={email} onChange={(e) => setEmail(e.target.value)}/>
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Secure Access Key</label>
                  <div className="relative">
                    <Lock className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input type={showPassword ? "text" : "password"} required className="w-full bg-slate-50 border-2 border-transparent focus:border-indigo-600 focus:bg-white rounded-[1.5rem] py-4.5 pl-14 pr-14 outline-none transition-all font-bold text-slate-700" placeholder="••••••••" value={password} onChange={(e) => setPassword(e.target.value)}/>
                    <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-indigo-600 transition-colors">
                      {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                    </button>
                  </div>
                </div>
                <button type="submit" disabled={isLoading} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-black py-5 rounded-[1.5rem] shadow-2xl shadow-indigo-100 transition-all flex items-center justify-center gap-3 group disabled:bg-indigo-400">
                  {isLoading ? <RefreshCw className="animate-spin" size={20} /> : <>AUTHENTICATE IDENTITY <ShieldCheck size={20} className="group-hover:scale-110 transition-transform" /></>}
                </button>
              </form>
            )}
          </div>
          <div className="bg-slate-50/50 p-8 border-t border-slate-100 text-center">
            <p className="text-[10px] text-slate-400 font-black uppercase tracking-[0.2em]">Live Registry Connection Active</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

