    is_system_admin BOOLEAN DEFAULT FALSE,
    status TEXT DEFAULT 'Active',
    must_change_password BOOLEAN DEFAULT TRUE,
    password_expiry TIMESTAMP WITH TIME ZONE DEFAULT (NOW() + interval '80 days'),
    password_hash_mock TEXT, -- Placeholder for project-based credential sync
    last_login TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Note: Ensure policies allow service-key access
-- ALTER TABLE profiles DISABLE ROW LEVEL SECURITY;
`.trim();

  const isSystemAdmin = currentUser?.is_system_admin || currentUser?.role === UserRole.ADMIN;

