const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [isCloudReady, setIsCloudReady] = useState(false);

  // Check if this specific browser profile is already configured for Cloud
  useEffect(() => {
    const stored = localStorage.getItem('unsg_settings');
    if (stored) {
      const settings: AppSettings = JSON.parse(stored);
      if (settings.supabaseUrl && settings.supabaseKey) {
        initSupabase(settings);
        checkConnection().then(connected => setIsCloudReady(connected));
      }
    }
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    const normalizedEmail = email.trim().toLowerCase();
    const normalizedPassword = password.trim();

    // 1. Root Admin Bypass (Always works, used to bootstrap new browsers)
    const adminEmail = 'aqandeel@gmail.com';
    const adminPass = 'Rodl@2026';

    if (normalizedEmail === adminEmail && normalizedPassword === adminPass) {
      setIsSuccess(true);
      setTimeout(() => {
        onLogin({
          id: 'SYS-ADMIN-001',
          email: adminEmail,
          full_name: 'System Administrator',
          role: UserRole.ADMIN,
          is_system_admin: true,
          status: AccountStatus.ACTIVE,
          must_change_password: false,
          password_expiry: new Date(Date.now() + 80 * 86400000).toISOString(),
          created_at: new Date().toISOString()
        });
      }, 600);
      return;
    } 

    // 2. Cloud-First Authentication
    // This allows users to log in on ANY browser once the Root Admin has set the API key
    let userFound: any = null;

    try {
      const cloudUsers = await fetchCloudUsers();
      if (cloudUsers) {
        const cloudMatch: any = cloudUsers.find((u: any) => u.email.toLowerCase() === normalizedEmail);
        if (cloudMatch && (cloudMatch.password_hash_mock === normalizedPassword)) {
          userFound = {
            ...cloudMatch,
            role: cloudMatch.role_id,
            password: cloudMatch.password_hash_mock
          };
          // Sync to local cache for offline/faster subsequent access
          const storedUsers = JSON.parse(localStorage.getItem('unsg_users') || '[]');
          const updatedLocal = [...storedUsers.filter((u: any) => u.email !== normalizedEmail), userFound];
          localStorage.setItem('unsg_users', JSON.stringify(updatedLocal));
        }
      }
    } catch (err) {
      console.warn("Cloud auth check skipped or failed:", err);
    }

    // 3. Local Cache Fallback (If cloud failed or is disconnected)
    if (!userFound) {
      const storedUsers = JSON.parse(localStorage.getItem('unsg_users') || '[]');
      userFound = storedUsers.find((u: any) => 
        u.email.trim().toLowerCase() === normalizedEmail && u.password.trim() === normalizedPassword
      );
    }

    if (userFound) {
      if (userFound.status === AccountStatus.DISABLED) {
        setError('Security Access Denied: This identity has been suspended by the Compliance Manager.');
        setIsLoading(false);
      } else {
        setIsSuccess(true);
        setTimeout(() => onLogin(userFound), 600);
      }
    } else {
      if (!isCloudReady && normalizedEmail !== adminEmail) {
        setError('System Isolation: This browser is not yet linked to the Global Cloud. Please log in as Root Admin first to configure the Cloud Engine.');
      } else {
        setError('Authentication Failure: Invalid credentials for this environment.');
      }
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4 relative overflow-hidden">
      {/* Animated Background Gradients */}
      <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none">
        <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-indigo-600 rounded-full blur-[120px]" />
        <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-blue-600 rounded-full blur-[120px]" />
      </div>

      <div className="w-full max-w-md relative z-10">
        <div className="bg-white rounded-[3rem] shadow-2xl overflow-hidden border border-white/10">
          <div className="p-10 md:p-14">
            <div className="flex flex-col items-center mb-10">
              <div className="bg-indigo-600 p-5 rounded-3xl shadow-2xl shadow-indigo-200 mb-8 transform hover:rotate-6 transition-transform duration-500">
                <ShieldCheck size={48} className="text-white" />
              </div>
              <h1 className="text-4xl font-black text-slate-900 tracking-tight">SanctionGuard</h1>
              <div className="flex items-center gap-2 mt-3">
                <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Global Identity Terminal</p>
                <div className={`flex items-center gap-1 px-2 py-0.5 rounded-full text-[8px] font-black uppercase border ${isCloudReady ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-amber-50 text-amber-600 border-amber-100'}`}>
                   {isCloudReady ? <><Wifi size={8}/> Linked</> : <><WifiOff size={8}/> Isolated</>}
                </div>
              </div>
            </div>

            {error && (
              <div className="mb-8 p-5 bg-red-50 border border-red-100 rounded-[1.5rem] flex items-start gap-4 text-red-600 text-[11px] leading-relaxed animate-in fade-in slide-in-from-top-2">
                <AlertCircle size={18} className="shrink-0 mt-0.5" />
                <p className="font-bold">{error}</p>
              </div>
            )}

            {isSuccess ? (
              <div className="flex flex-col items-center justify-center py-10 animate-in zoom-in-95 duration-300">
                <div className="h-20 w-20 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mb-6 shadow-xl shadow-emerald-50">
                  <CheckCircle size={40} />
                </div>
                <h3 className="text-2xl font-black text-slate-900">Access Granted</h3>
                <p className="text-slate-400 text-sm mt-2 font-medium">Resuming global session...</p>
              </div>
            ) : (
              <form onSubmit={handleLogin} className="space-y-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Internal Identity (Email)</label>
                  <div className="relative">
                    <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input type="email" required className="w-full bg-slate-50 border-2 border-transparent focus:border-indigo-600 focus:bg-white rounded-[1.5rem] py-4.5 pl-14 pr-5 outline-none transition-all font-bold text-slate-700" placeholder="user@rodlme.com" value={email} onChange={(e) => setEmail(e.target.value)}/>
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Secure Access Key</label>
                  <div className="relative">
                    <Lock className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input type={showPassword ? "text" : "password"} required className="w-full bg-slate-50 border-2 border-transparent focus:border-indigo-600 focus:bg-white rounded-[1.5rem] py-4.5 pl-14 pr-14 outline-none transition-all font-bold text-slate-700" placeholder="••••••••" value={password} onChange={(e) => setPassword(e.target.value)}/>
                    <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-indigo-600 transition-colors">
