              <h1 className="text-3xl font-black text-slate-900 tracking-tight">SanctionGuard</h1>
              <div className={`mt-3 flex items-center gap-1.5 px-3 py-1 rounded-full text-[9px] font-black uppercase border ${isCloudReady ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-amber-50 text-amber-600 border-amber-100'}`}>
                 {isCloudReady ? <><Wifi size={10}/> Global Node Active</> : <><WifiOff size={10}/> Isolated Local Node</>}
              </div>
            </div>

            {error && (
