import { createClient } from '@supabase/supabase-js';
import { Client, AppSettings, RiskLevel, UserProfile } from '../types';

let supabase: any = null;

export const initSupabase = (settings: AppSettings) => {
  if (settings.supabaseUrl && settings.supabaseKey) {
    supabase = createClient(settings.supabaseUrl, settings.supabaseKey);
    return true;
  }
  return false;
};

export const checkConnection = async () => {
  if (!supabase) return false;
  try {
    const { error } = await supabase.from('profiles').select('email').limit(1);
    return !error;
  } catch {
    return false;
  }
};

// --- CLIENT OPERATIONS ---

export const fetchCloudClients = async (): Promise<Client[] | null> => {
  if (!supabase) return null;
  const { data, error } = await supabase.from('clients').select('*').order('created_at', { ascending: false });
  if (error) throw error;
  return data;
};

export const upsertCloudClient = async (client: Client) => {
  if (!supabase) return;
  const { error } = await supabase.from('clients').upsert([client], { onConflict: 'id' });
  if (error) throw error;
};

export const deleteCloudClient = async (id: string) => {
  if (!supabase) return;
  const { error } = await supabase.from('clients').delete().eq('id', id);
  if (error) throw error;
};

// --- USER PROFILE OPERATIONS ---

export const fetchCloudUsers = async (): Promise<UserProfile[] | null> => {
  if (!supabase) return null;
  try {
    const { data, error } = await supabase.from('profiles').select('*');
    if (error) return null;
    return data;
  } catch (err) {
    return null;
  }
};

export const upsertCloudUser = async (user: any) => {
  if (!supabase) return;

  const dbProfile = {
    id: user.id,
    email: user.email.toLowerCase().trim(),
    full_name: user.full_name,
    role_id: user.role,
    status: user.status || 'Active',
    is_system_admin: user.is_system_admin === true || user.role === 'Compliance Manager',
    must_change_password: user.must_change_password,
    password_expiry: user.password_expiry,
    password_hash_mock: user.password,
    created_at: user.created_at || new Date().toISOString()
  };

  const { error } = await supabase.from('profiles').upsert([dbProfile], { onConflict: 'email' });
  if (error) throw new Error(error.message);
};

export const deleteCloudUser = async (email: string) => {
  if (!supabase) return;
  const { error } = await supabase.from('profiles').delete().eq('email', email.toLowerCase().trim());
  if (error) throw new Error(error.message);
};

export const subscribeToClients = (onUpdate: () => void) => {
  if (!supabase) return null;
  return supabase.channel('clients-changes').on('postgres_changes', { event: '*', schema: 'public', table: 'clients' }, onUpdate).subscribe();
};

export const unsubscribeFromClients = async (channel: any) => {
  if (supabase && channel) await supabase.removeChannel(channel);
};

