                          <input type="password" className="w-full bg-white border border-indigo-100 rounded-xl py-3 px-4 text-xs font-bold outline-none focus:border-indigo-600 transition-all" placeholder="Paste API Key here" value={supabaseKey} onChange={(e) => setSupabaseKey(e.target.value)}/>
