            <h2 className="text-2xl font-black text-slate-900 tracking-tight">System Governance</h2>
            <p className="text-[10px] text-amber-600 font-black uppercase tracking-[0.2em] mt-1">Technical Control Plane</p>
          </div>
        </div>
        <div className="flex bg-slate-50 p-1.5 rounded-2xl border border-slate-100">
            <button onClick={() => setActiveTab('users')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all uppercase tracking-tight ${activeTab === 'users' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>Identities</button>
            <button onClick={() => setActiveTab('config')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all uppercase tracking-tight ${activeTab === 'config' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>Cloud Engine</button>
            <button onClick={() => setActiveTab('logs')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all uppercase tracking-tight ${activeTab === 'logs' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>Audit Logs</button>
        </div>
      </div>

      {activeTab === 'users' && (
        <div className="space-y-6 animate-in fade-in duration-500">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 bg-white rounded-[2.5rem] border border-slate-100 overflow-hidden shadow-sm">
                <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                   <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em] flex items-center gap-3">
                      Identity Registry {isSyncing && <RefreshCw size={16} className="animate-spin text-indigo-500" />}
                   </h3>
                   <button onClick={() => setIsUserModalOpen(true)} className="bg-indigo-600 text-white px-6 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100">
                     <Plus size={16} /> Provision User
                   </button>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                      <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">
                        <tr>
                          <th className="px-10 py-5">Identity</th>
                          <th className="px-10 py-5">Role</th>
                          <th className="px-10 py-5 text-right">Controls</th>
