                            <div className="font-black text-slate-900 text-sm">aqandeel@gmail.com</div>
                            <div className="text-[10px] text-amber-600 font-bold uppercase">System Authority</div>
                          </td>
                          <td className="px-10 py-5"><span className="px-3 py-1 bg-slate-900 text-white text-[9px] font-black rounded-lg uppercase">Root Admin</span></td>
