import React, { useState, useEffect } from 'react';
import { ShieldCheck, Lock, Mail, AlertCircle, Loader2, Eye, EyeOff, CheckCircle, RefreshCw, Wifi, WifiOff, Database, ChevronDown, ChevronUp, Key } from 'lucide-react';
import { UserProfile, UserRole, AccountStatus, AppSettings } from '../types';
import { fetchCloudUsers, initSupabase, checkConnection } from '../services/cloudDb';

interface LoginProps {
  onLogin: (user: UserProfile) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [supabaseKey, setSupabaseKey] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showCloudSetup, setShowCloudSetup] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [isCloudReady, setIsCloudReady] = useState(false);

  useEffect(() => {
    const stored = localStorage.getItem('unsg_settings');
    if (stored) {
      try {
        const settings: AppSettings = JSON.parse(stored);
        if (settings.supabaseUrl && settings.supabaseKey) {
          initSupabase(settings);
          checkConnection().then(connected => setIsCloudReady(connected));
        }
      } catch (e) {
        console.error("Failed to restore cloud settings", e);
      }
    }
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    const normalizedEmail = email.trim().toLowerCase();
    const normalizedPassword = password.trim();

    // 1. CRITICAL: Root Admin Safety Bypass (Hardened check)
    if (normalizedEmail === 'aqandeel@gmail.com' && normalizedPassword === 'Rodl@2026') {
      setIsSuccess(true);
      setTimeout(() => {
        onLogin({
          id: 'SYS-ADMIN-ROOT',
          email: 'aqandeel@gmail.com',
          full_name: 'System Administrator',
          role: UserRole.ADMIN, 
          is_system_admin: true, 
          status: AccountStatus.ACTIVE,
          must_change_password: false,
          password_expiry: '',
          created_at: new Date().toISOString()
        });
      }, 600);
      return;
    }

    // 2. Cloud Configuration Bootstrap
    if (!isCloudReady && supabaseKey) {
      const tempSettings: AppSettings = {
        autoSync: true,
        syncIntervalMinutes: 1440,
        sourceUrl: '',
        lastSync: 'Never',
        nextSync: '',
        supabaseUrl: 'https://wbjiokaryxrjicavcvwx.supabase.co',
        supabaseKey: supabaseKey
      };

      const initialized = initSupabase(tempSettings);
      const connected = initialized ? await checkConnection() : false;

      if (!connected) {
        setError('Cloud Handshake Failed: Invalid Supabase Key.');
        setIsLoading(false);
        return;
      }
      localStorage.setItem('unsg_settings', JSON.stringify(tempSettings));
      setIsCloudReady(true);
    }

    // 3. Authenticate against Registry
    let userFound: any = null;

    try {
      const cloudUsers = await fetchCloudUsers();
      if (cloudUsers) {
        const cloudMatch: any = cloudUsers.find((u: any) => u.email.toLowerCase().trim() === normalizedEmail);
        if (cloudMatch && (cloudMatch.password_hash_mock === normalizedPassword)) {
          userFound = {
            ...cloudMatch,
            role: cloudMatch.role_id,
            password: cloudMatch.password_hash_mock
          };
          const storedUsers = JSON.parse(localStorage.getItem('unsg_users') || '[]');
          const updatedLocal = [...storedUsers.filter((u: any) => u.email.toLowerCase() !== normalizedEmail), userFound];
          localStorage.setItem('unsg_users', JSON.stringify(updatedLocal));
        }
      }
    } catch (err) {
      console.warn("Cloud Registry unreachable, attempting local vault fallback.");
    }

    if (!userFound) {
      const storedUsers = JSON.parse(localStorage.getItem('unsg_users') || '[]');
      userFound = storedUsers.find((u: any) => 
        u.email.trim().toLowerCase() === normalizedEmail && (u.password || u.password_hash_mock)?.trim() === normalizedPassword
      );
    }

    if (userFound) {
      if (userFound.status === AccountStatus.DISABLED) {
        setError('Security Protocol: This account has been suspended.');
        setIsLoading(false);
      } else {
        setIsSuccess(true);
        setTimeout(() => onLogin(userFound), 600);
      }
    } else {
      setError('Access Denied: Invalid credentials. Ensure email and security key are correct.');
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#08090d] flex items-center justify-center p-4 relative overflow-hidden">
      <div className="absolute top-0 left-0 w-full h-full opacity-30 pointer-events-none">
        <div className="absolute top-[-20%] left-[-10%] w-[60%] h-[60%] bg-indigo-900 rounded-full blur-[180px]" />
        <div className="absolute bottom-[-20%] right-[-10%] w-[60%] h-[60%] bg-blue-900 rounded-full blur-[180px]" />
      </div>

      <div className="w-full max-w-md relative z-10">
        <div className="bg-white rounded-[3rem] shadow-2xl overflow-hidden border border-white/20">
          <div className="p-10 md:p-14">
            <div className="flex flex-col items-center mb-10 text-center">
              {/* BRAND LOGO */}
              <div className="mb-8 transform hover:scale-105 transition-transform duration-500">
                 <img 
                   src="https://raw.githubusercontent.com/AnasQandeel/RPME-Logo/main/RPME%20Logo.png" 
                   alt="RPME Limited Logo" 
                   className="h-32 md:h-40 w-auto object-contain"
                   onError={(e) => {
                     // Fallback if image fails to load
                     e.currentTarget.src = "https://placehold.co/400x400/indigo/white?text=RPME+LIMITED";
                   }}
                 />
              </div>
              <h1 className="text-3xl font-black text-slate-900 tracking-tighter uppercase">SanctionGuard</h1>
              <div className={`mt-4 flex items-center gap-2 px-4 py-1.5 rounded-full text-[10px] font-black uppercase border tracking-widest ${isCloudReady ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-amber-50 text-amber-600 border-amber-100'}`}>
                 {isCloudReady ? <><Wifi size={12}/> Global Cloud Active</> : <><WifiOff size={12}/> Local Isolated Node</>}
              </div>
            </div>

            {error && (
              <div className="mb-8 p-5 bg-red-50 border border-red-100 rounded-[1.5rem] flex items-start gap-4 text-red-600 text-[11px] font-bold animate-in fade-in slide-in-from-top-2">
                <AlertCircle size={18} className="shrink-0 mt-0.5" />
                <p>{error}</p>
              </div>
            )}

            {isSuccess ? (
              <div className="flex flex-col items-center justify-center py-12 animate-in zoom-in-95 duration-300">
                <div className="h-20 w-20 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mb-6 shadow-xl shadow-emerald-50">
                  <CheckCircle size={40} />
                </div>
                <h3 className="text-2xl font-black text-slate-900 uppercase tracking-widest">Access Granted</h3>
              </div>
            ) : (
              <form onSubmit={handleLogin} className="space-y-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Identity (Email)</label>
                  <div className="relative">
                    <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input type="email" required className="w-full bg-slate-50 border-2 border-transparent focus:border-indigo-600 focus:bg-white rounded-[1.5rem] py-5 pl-14 pr-5 outline-none transition-all font-bold text-slate-700" placeholder="user@rodlme.com" value={email} onChange={(e) => setEmail(e.target.value)}/>
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Security Key</label>
                  <div className="relative">
                    <Lock className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input type={showPassword ? "text" : "password"} required className="w-full bg-slate-50 border-2 border-transparent focus:border-indigo-600 focus:bg-white rounded-[1.5rem] py-5 pl-14 pr-14 outline-none transition-all font-bold text-slate-700" placeholder="••••••••" value={password} onChange={(e) => setPassword(e.target.value)}/>
                    <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-400 hover:text-indigo-600 transition-colors">
                      {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                    </button>
                  </div>
                </div>

                {!isCloudReady && (
                  <div className="pt-2">
                    <button type="button" onClick={() => setShowCloudSetup(!showCloudSetup)} className="text-[10px] font-black text-indigo-600 uppercase tracking-widest flex items-center gap-1 hover:underline ml-2">
                      {showCloudSetup ? <ChevronUp size={12}/> : <ChevronDown size={12}/>} Link Global Registry
                    </button>
                    {showCloudSetup && (
                      <div className="mt-4 p-5 bg-indigo-50/50 border border-indigo-100 rounded-[1.5rem] space-y-4 animate-in slide-in-from-top-2">
                        <div className="space-y-1">
                          <label className="text-[9px] font-black text-indigo-400 uppercase tracking-widest ml-1">Supabase Secret Key</label>
                          <input type="password" className="w-full bg-white border border-indigo-100 rounded-xl py-3 px-4 text-xs font-bold outline-none focus:border-indigo-600 transition-all" placeholder="Paste API Key here" value={supabaseKey} onChange={(e) => setSupabaseKey(e.target.value)}/>
                        </div>
                      </div>
                    )}
                  </div>
                )}

                <button type="submit" disabled={isLoading} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-black py-5.5 rounded-[1.5rem] shadow-2xl transition-all flex items-center justify-center gap-3 active:scale-95 disabled:opacity-50">
                  {isLoading ? <RefreshCw className="animate-spin" size={20} /> : 'AUTHENTICATE SESSION'}
                </button>
              </form>
            )}
          </div>
          <div className="bg-slate-50/50 p-8 text-center border-t border-slate-100">
             <p className="text-[10px] text-slate-400 font-black uppercase tracking-[0.2em]">Compliance Level 4 Secure Node</p>
          </div>
        </div>
      </div>
    </div>
  );
};

