    "Client Name": "", "Services Provided": [], "Engagement Year": "", "Engagement Date": "",
    "Onboarding Date": "", "Date of QFC Incorporation or Registration": "", "CR Expired date": "",
    "Entity Card No": "", "Entity Card Expiry": "", "License": "", "License Expiry": "",
    "Nature of Business": "", "Registered Address": "", "Telephone Number": "", "E Mail": "",
    "Website": "", "Directors Names": [], "Significant Shareholders": [], "UBO Details": [],
    "Authorized Signatory": [], "Secretary": "", "Senior Executive Function": "",
    "Approved Auditor": "", "Company Type": "", "kyc_status": KYCStatus.DRAFT, "entity_type": EntityType.CORPORATE
  };

  const [formData, setFormData] = useState(initialForm);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newClient = { 
      ...formData, 
      id: `C-${Math.random().toString(36).substr(2, 9)}`, 
      created_at: new Date().toISOString(),
      created_by: currentUserId,
      riskLevel: RiskLevel.NONE,
      entity_type: entityType
    };
    onAddClient(newClient);
    setFormData(initialForm);
    setIsModalOpen(false);
  };

  const handleUpdateStatus = (status: KYCStatus) => {
    if (!selectedClient || !onUpdateClient) return;

    if (status === KYCStatus.APPROVED && selectedClient.created_by === currentUserId) {
      alert("Segregation of Duties Violation: You cannot approve an entry you created yourself.");
      return;
    }

    const updated = { 
      ...selectedClient, 
      kyc_status: status,
      [status === KYCStatus.APPROVED ? 'approved_by' : 'reviewed_by']: currentUserId 
    };
    onUpdateClient(updated);
    setSelectedClient(updated);
  };

  const getStatusColor = (status: KYCStatus) => {
    switch (status) {
      case KYCStatus.APPROVED: return 'bg-green-100 text-green-700 border-green-200';
      case KYCStatus.PENDING_REVIEW: return 'bg-amber-100 text-amber-700 border-amber-200';
      case KYCStatus.REJECTED: return 'bg-red-100 text-red-700 border-red-200';
      default: return 'bg-gray-100 text-gray-700 border-gray-200';
    }
  };

  const safeClients = Array.isArray(clients) ? clients : [];

  return (
