              <Plus size={20} /> New Entity
            </button>
          )}
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-sm border border-gray-100 overflow-x-auto overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-gray-50/50 text-gray-400">
            <tr>
              <th className="px-10 py-5 text-[10px] font-black uppercase tracking-widest">Type</th>
              <th className="px-10 py-5 text-[10px] font-black uppercase tracking-widest">Client Name</th>
