              <th className="px-10 py-5 text-[10px] font-black uppercase tracking-widest">Risk Level</th>
              <th className="px-10 py-5 text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {safeClients.map(client => (
              <tr key={client.id} className="hover:bg-indigo-50/20 cursor-pointer transition-colors" onClick={() => setSelectedClient(client)}>
