const PersonRecordList = ({ label, items, onChange }: { label: string, items: PersonRecord[], onChange: (items: PersonRecord[]) => void }) => {
  const safeItems = Array.isArray(items) ? items : [];
  const addItem = () => onChange([...safeItems, { name: '', qid_passport: '', nationality: '', dob: '' }]);
  const updateItem = (index: number, field: keyof PersonRecord, value: string) => {
    const newItems = [...safeItems];
    newItems[index] = { ...newItems[index], [field]: value };
    onChange(newItems);
  };
  const removeItem = (index: number) => onChange(safeItems.filter((_, i) => i !== index));

  return (
    <div className="md:col-span-3 space-y-4">
      <div className="flex justify-between items-center bg-emerald-950/5 p-4 rounded-2xl">
        <label className="text-[9px] font-black text-emerald-900 uppercase tracking-widest ml-2">{label}</label>
        <button type="button" onClick={addItem} className="text-[9px] uppercase tracking-widest flex items-center gap-2 bg-emerald-800 text-white px-4 py-2 rounded-xl font-black hover:bg-emerald-900 transition-all">
          <UserPlus size={14} /> Add Identity
        </button>
      </div>
      <div className="grid grid-cols-1 gap-4">
        {safeItems.map((item, idx) => (
          <div key={idx} className="grid grid-cols-1 md:grid-cols-4 gap-4 p-6 bg-gray-50 rounded-[2rem] border border-gray-100 relative group">
            <InputField label="Full Legal Name" value={item.name} onChange={(v: string) => updateItem(idx, 'name', v)} />
            <InputField label="QID / ID Document" value={item.qid_passport} onChange={(v: string) => updateItem(idx, 'qid_passport', v)} />
            <InputField label="Nationality" value={item.nationality} onChange={(v: string) => updateItem(idx, 'nationality', v)} />
            <div className="flex items-end gap-3">
              <div className="flex-1">
                <InputField label="Date of Birth" type="date" value={item.dob} onChange={(v: string) => updateItem(idx, 'dob', v)} />
              </div>
              <button type="button" onClick={() => removeItem(idx)} className="p-4 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all">
                <Trash2 size={20} />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

interface ClientManagerProps {
  clients: Client[];
  onAddClient: (client: Client) => void;
  onDeleteClient: (id: string) => void;
  onUpdateClient?: (client: Client) => void;
  onRefresh: () => void;
  currentUserRole: UserRole;
  currentUserId: string;
}

const ClientManager: React.FC<ClientManagerProps> = ({ clients, onAddClient, onDeleteClient, onUpdateClient, onRefresh, currentUserRole, currentUserId }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [entityType, setEntityType] = useState<EntityType>(EntityType.CORPORATE);

  const LOGO_URL = "https://raw.githubusercontent.com/AnasQandeel/RPME-Logo/main/RPME%20Logo.png";

  const initialForm: any = {
    "No": "", "Status": "Pending", "QFC No": "", "Legal Structure": "", "Company Nationality": "",
    "Client Name": "", "Services Provided": [], "Engagement Year": "", "Engagement Date": "",
    "Onboarding Date": "", "Date of QFC Incorporation or Registration": "", "CR Expired date": "",
    "Entity Card No": "", "Entity Card Expiry": "", "License": "", "License Expiry": "",
    "Nature of Business": "", "Registered Address": "", "Telephone Number": "", "E Mail": "",
    "Website": "", "Directors Names": [], "Significant Shareholders": [], "UBO Details": [],
    "Authorized Signatory": [], "Secretary": "", "Senior Executive Function": "",
    "Approved Auditor": "", "Company Type": "", "kyc_status": KYCStatus.DRAFT, "entity_type": EntityType.CORPORATE
  };

  const [formData, setFormData] = useState(initialForm);

  const handleOpenProvisionModal = () => {
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newClient = { ...formData, id: `RPME-${Math.random().toString(36).substr(2, 6).toUpperCase()}`, created_at: new Date().toISOString(), created_by: currentUserId, riskLevel: RiskLevel.NONE, entity_type: entityType };
    onAddClient(newClient);
    setFormData(initialForm);
    setIsModalOpen(false);
  };

  const handleUpdateStatus = (status: KYCStatus) => {
    if (!selectedClient || !onUpdateClient) return;
    if (status === KYCStatus.APPROVED && selectedClient.created_by === currentUserId) {
      alert("Segregation of Duties Violation: Approver must be different from Creator.");
      return;
    }
    const updated = { ...selectedClient, kyc_status: status, [status === KYCStatus.APPROVED ? 'approved_by' : 'reviewed_by']: currentUserId };
    onUpdateClient(updated);
    setSelectedClient(updated);
  };

  const handlePrint = () => { window.print(); };

  const getStatusColor = (status: KYCStatus) => {
    switch (status) {
      case KYCStatus.APPROVED: return 'bg-emerald-100 text-emerald-800 border-emerald-200';
      case KYCStatus.PENDING_REVIEW: return 'bg-amber-100 text-amber-800 border-amber-200';
      case KYCStatus.REJECTED: return 'bg-red-100 text-red-800 border-red-200';
      default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  return (
    <div className="space-y-8 relative z-0">
      <div className="flex justify-between items-center bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm">
        <div>
          <h2 className="text-3xl font-black text-emerald-950 tracking-tighter uppercase">Entity Registry</h2>
          <p className="text-[10px] text-emerald-700 mt-1 uppercase tracking-[0.4em] font-black">Authorized RPME Compliance Node</p>
        </div>
        <div className="flex gap-4 relative z-50">
          <button onClick={onRefresh} className="p-4 text-gray-400 hover:text-emerald-800 bg-gray-50 rounded-2xl transition-all"><RefreshCw size={24}/></button>
          {(currentUserRole === UserRole.DATA_ENTRY || currentUserRole === UserRole.ADMIN) && (
            <button 
              type="button" 
              onClick={handleOpenProvisionModal} 
              className="bg-emerald-800 text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center gap-3 shadow-2xl shadow-emerald-900/10 hover:bg-emerald-900 transition-all active:scale-95 cursor-pointer"
            >
              <Plus size={20} /> Provision New Entity
            </button>
          )}
        </div>
      </div>

      <div className="bg-white rounded-[3rem] shadow-sm border border-gray-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50/50">
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Type</th>
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Entity Name</th>
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">KYC Status</th>
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Risk Index</th>
                <th className="px-10 py-6 text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {clients.map(client => (
                <tr key={client.id} className="hover:bg-emerald-50/20 cursor-pointer transition-colors group" onClick={() => setSelectedClient(client)}>
                  <td className="px-10 py-6">
                    <span className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-xl text-[9px] font-black uppercase border ${client.entity_type === EntityType.INDIVIDUAL ? 'bg-amber-50 text-amber-800 border-amber-100' : 'bg-emerald-50 text-emerald-800 border-emerald-100'}`}>
                      {client.entity_type === EntityType.INDIVIDUAL ? <Users size={12}/> : <Landmark size={12}/>}
                      {client.entity_type}
                    </span>
                  </td>
                  <td className="px-10 py-6 font-black text-emerald-950 text-sm tracking-tight">{client["Client Name"]}</td>
                  <td className="px-10 py-6">
                    <span className={`px-3 py-1.5 rounded-full text-[9px] font-black uppercase border-2 ${getStatusColor(client.kyc_status)}`}>
                      {client.kyc_status}
