const InputField = ({ label, value, onChange, type = "text", placeholder = "", required = false }: any) => (
  <div className="space-y-2">
    <div className="flex justify-between">
        <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest block ml-1">{label}</label>
        {required && <span className="text-[9px] text-amber-600 font-black uppercase">Required</span>}
    </div>
    <input 
      type={type} 
      placeholder={placeholder}
      className="w-full bg-gray-50 border-2 border-transparent rounded-2xl p-4 text-sm font-bold text-emerald-950 focus:border-emerald-800 focus:bg-white outline-none transition-all" 
      value={value} 
      onChange={e => onChange(e.target.value)} 
      required={required} 
    />
  </div>
);

const PersonRecordList = ({ label, items, onChange }: { label: string, items: PersonRecord[], onChange: (items: PersonRecord[]) => void }) => {
  const safeItems = Array.isArray(items) ? items : [];
  const addItem = () => onChange([...safeItems, { name: '', qid_passport: '', nationality: '', dob: '' }]);
  const updateItem = (index: number, field: keyof PersonRecord, value: string) => {
    const newItems = [...safeItems];
    newItems[index] = { ...newItems[index], [field]: value };
    onChange(newItems);
  };
  const removeItem = (index: number) => onChange(safeItems.filter((_, i) => i !== index));

  return (
    <div className="md:col-span-3 space-y-4">
      <div className="flex justify-between items-center bg-emerald-950/5 p-4 rounded-2xl">
        <label className="text-[9px] font-black text-emerald-900 uppercase tracking-widest ml-2">{label}</label>
        <button type="button" onClick={addItem} className="text-[9px] uppercase tracking-widest flex items-center gap-2 bg-emerald-800 text-white px-4 py-2 rounded-xl font-black hover:bg-emerald-900 transition-all">
          <UserPlus size={14} /> Add Identity
        </button>
      </div>
      <div className="grid grid-cols-1 gap-4">
        {safeItems.map((item, idx) => (
          <div key={idx} className="grid grid-cols-1 md:grid-cols-4 gap-4 p-6 bg-gray-50 rounded-[2rem] border border-gray-100 relative group">
            <InputField label="Full Legal Name" value={item.name} onChange={(v: string) => updateItem(idx, 'name', v)} />
            <InputField label="QID / ID Document" value={item.qid_passport} onChange={(v: string) => updateItem(idx, 'qid_passport', v)} />
            <InputField label="Nationality" value={item.nationality} onChange={(v: string) => updateItem(idx, 'nationality', v)} />
            <div className="flex items-end gap-3">
              <div className="flex-1">
                <InputField label="Date of Birth" type="date" value={item.dob} onChange={(v: string) => updateItem(idx, 'dob', v)} />
              </div>
              <button type="button" onClick={() => removeItem(idx)} className="p-4 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all">
                <Trash2 size={20} />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

interface ClientManagerProps {
  clients: Client[];
  onAddClient: (client: Client) => void;
  onDeleteClient: (id: string) => void;
  onUpdateClient?: (client: Client) => void;
  onRefresh: () => void;
  currentUserRole: UserRole;
  currentUserId: string;
}

const ClientManager: React.FC<ClientManagerProps> = ({ clients, onAddClient, onDeleteClient, onUpdateClient, onRefresh, currentUserRole, currentUserId }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [entityType, setEntityType] = useState<EntityType>(EntityType.CORPORATE);

  const LOCAL_LOGO = "/logo.png";
  const GITHUB_LOGO = "https://raw.githubusercontent.com/AnasQandeel/RPME-Logo/main/RPME%20Logo.png";

  const initialForm: any = {
    "No": "", "Status": "Pending", "QFC No": "", "Legal Structure": "", "Company Nationality": "",
    "Client Name": "", "Services Provided": [], "Engagement Year": "", "Engagement Date": "",
    "Onboarding Date": "", "Date of QFC Incorporation or Registration": "", "CR Expired date": "",
    "Entity Card No": "", "Entity Card Expiry": "", "License": "", "License Expiry": "",
    "Nature of Business": "", "Registered Address": "", "Telephone Number": "", "E Mail": "",
    "Website": "", "Directors Names": [], "Significant Shareholders": [], "UBO Details": [],
    "Authorized Signatory": [], "Secretary": "", "Senior Executive Function": "",
    "Approved Auditor": "", "Company Type": "", "kyc_status": KYCStatus.DRAFT, "entity_type": EntityType.CORPORATE
  };

  const [formData, setFormData] = useState(initialForm);

  const handleOpenProvisionModal = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newClient = { ...formData, id: `RPME-${Math.random().toString(36).substr(2, 6).toUpperCase()}`, created_at: new Date().toISOString(), created_by: currentUserId, riskLevel: RiskLevel.NONE, entity_type: entityType };
    onAddClient(newClient);
    setFormData(initialForm);
    setIsModalOpen(false);
  };

  const handleUpdateStatus = (status: KYCStatus) => {
    if (!selectedClient || !onUpdateClient) return;
    if (status === KYCStatus.APPROVED && selectedClient.created_by === currentUserId) {
      alert("Segregation of Duties Violation: Approver must be different from Creator.");
      return;
    }
    const updated = { ...selectedClient, kyc_status: status, [status === KYCStatus.APPROVED ? 'approved_by' : 'reviewed_by']: currentUserId };
    onUpdateClient(updated);
    setSelectedClient(updated);
  };

  const handlePrint = () => { window.print(); };

  const getStatusColor = (status: KYCStatus) => {
    switch (status) {
      case KYCStatus.APPROVED: return 'bg-emerald-100 text-emerald-800 border-emerald-200';
      case KYCStatus.PENDING_REVIEW: return 'bg-amber-100 text-amber-800 border-amber-200';
      case KYCStatus.REJECTED: return 'bg-red-100 text-red-800 border-red-200';
      default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  return (
    <div className="space-y-8 relative">
      <div className="flex justify-between items-center bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm relative z-10">
        <div>
          <h2 className="text-3xl font-black text-emerald-950 tracking-tighter uppercase">Entity Registry</h2>
          <p className="text-[10px] text-emerald-700 mt-1 uppercase tracking-[0.4em] font-black">Authorized RPME Compliance Node</p>
        </div>
        <div className="flex gap-4 relative z-50">
          <button onClick={onRefresh} className="p-4 text-gray-400 hover:text-emerald-800 bg-gray-50 rounded-2xl transition-all cursor-pointer"><RefreshCw size={24}/></button>
          {(currentUserRole === UserRole.DATA_ENTRY || currentUserRole === UserRole.ADMIN) && (
            <button 
              type="button" 
              onClick={handleOpenProvisionModal} 
              className="bg-emerald-800 text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center gap-3 shadow-2xl shadow-emerald-900/10 hover:bg-emerald-900 transition-all active:scale-95 cursor-pointer relative z-[60]"
            >
              <Plus size={20} /> Provision New Entity
            </button>
          )}
        </div>
      </div>

      <div className="bg-white rounded-[3rem] shadow-sm border border-gray-100 overflow-hidden relative z-0">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50/50">
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Type</th>
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Entity Name</th>
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">KYC Status</th>
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Risk Index</th>
                <th className="px-10 py-6 text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {clients.map(client => (
                <tr key={client.id} className="hover:bg-emerald-50/20 cursor-pointer transition-colors group" onClick={() => setSelectedClient(client)}>
                  <td className="px-10 py-6">
                    <span className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-xl text-[9px] font-black uppercase border ${client.entity_type === EntityType.INDIVIDUAL ? 'bg-amber-50 text-amber-800 border-amber-100' : 'bg-emerald-50 text-emerald-800 border-emerald-100'}`}>
                      {client.entity_type === EntityType.INDIVIDUAL ? <Users size={12}/> : <Landmark size={12}/>}
                      {client.entity_type}
                    </span>
                  </td>
                  <td className="px-10 py-6 font-black text-emerald-950 text-sm tracking-tight">{client["Client Name"]}</td>
                  <td className="px-10 py-6">
                    <span className={`px-3 py-1.5 rounded-full text-[9px] font-black uppercase border-2 ${getStatusColor(client.kyc_status)}`}>
                      {client.kyc_status}
                    </span>
                  </td>
                  <td className="px-10 py-6">
                    <span className={`px-2 py-0.5 rounded-md text-[9px] font-black uppercase ${client.riskLevel === RiskLevel.HIGH ? 'bg-red-500 text-white' : 'bg-gray-100 text-gray-400'}`}>
                      {client.riskLevel}
                    </span>
                  </td>
                  <td className="px-10 py-6 text-right">
                    <button className="p-3 text-emerald-800 bg-gray-50 rounded-xl opacity-0 group-hover:opacity-100 transition-all"><Eye size={20}/></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-xl z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-6xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl animate-in zoom-in-95 duration-300">
            <div className="bg-emerald-900 p-10 text-white flex justify-between items-center shrink-0">
              <div className="flex items-center gap-6">
                 <div>
                    <h3 className="text-3xl font-black tracking-tight uppercase">Identity Provisioning</h3>
                    <p className="text-[10px] opacity-70 mt-2 uppercase tracking-widest font-black">Regulatory Onboarding Workflow</p>
                 </div>
                 <div className="flex bg-white/10 p-1.5 rounded-2xl border border-white/20">
                    <button type="button" onClick={() => setEntityType(EntityType.CORPORATE)} className={`px-6 py-2 rounded-xl text-xs font-black transition-all uppercase tracking-tight ${entityType === EntityType.CORPORATE ? 'bg-white text-emerald-900 shadow-sm' : 'text-white hover:bg-white/5'}`}>Corporate</button>
                    <button type="button" onClick={() => setEntityType(EntityType.INDIVIDUAL)} className={`px-6 py-2 rounded-xl text-xs font-black transition-all uppercase tracking-tight ${entityType === EntityType.INDIVIDUAL ? 'bg-white text-emerald-900 shadow-sm' : 'text-white hover:bg-white/5'}`}>Individual</button>
                 </div>
              </div>
              <button type="button" onClick={() => setIsModalOpen(false)} className="bg-white/10 p-3 rounded-full hover:bg-white/20 transition-all"><X size={24}/></button>
            </div>

            <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-10 space-y-10 custom-scrollbar">
              <FormSection title="Core Registry" icon={<Landmark size={18}/>}>
                <InputField label="Entity Legal Name" value={formData["Client Name"]} onChange={(v:any)=>setFormData({...formData, "Client Name": v})} required />
                <InputField label="File Reference No" value={formData["No"]} onChange={(v:any)=>setFormData({...formData, "No": v})} required />
                {entityType === EntityType.CORPORATE && (
                  <InputField label="QFC Registration No" value={formData["QFC No"]} onChange={(v:any)=>setFormData({...formData, "QFC No": v})} />
                )}
                <InputField label="Jurisdiction" value={formData["Company Nationality"]} onChange={(v:any)=>setFormData({...formData, "Company Nationality": v})} required />
                <InputField label="Legal Status" value={formData["Legal Structure"]} onChange={(v:any)=>setFormData({...formData, "Legal Structure": v})} />
              </FormSection>

              <FormSection title="Contact Protocol" icon={<Mail size={18}/>}>
                <InputField label="Official Email" value={formData["E Mail"]} onChange={(v:any)=>setFormData({...formData, "E Mail": v})} required />
                <InputField label="Phone System" value={formData["Telephone Number"]} onChange={(v:any)=>setFormData({...formData, "Telephone Number": v})} />
                <div className="md:col-span-1"></div>
                <div className="md:col-span-3">
                  <InputField label="Registered Physical Address" value={formData["Registered Address"]} onChange={(v:any)=>setFormData({...formData, "Registered Address": v})} required />
                </div>
              </FormSection>

              <div className="flex justify-end gap-4 pb-12 sticky bottom-0 bg-white/80 backdrop-blur-md pt-6 border-t border-gray-100 z-10">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-10 py-5 font-black text-[10px] uppercase tracking-widest text-gray-400 hover:text-gray-600">Cancel</button>
                <button type="submit" className="bg-emerald-800 text-white px-16 py-5 rounded-[1.5rem] font-black text-[10px] uppercase tracking-widest shadow-2xl shadow-emerald-900/10 hover:bg-emerald-900 transition-all flex items-center gap-3 active:scale-95">
                  <CheckCircle2 size={24}/> Initialize Profile
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {selectedClient && (
        <div className="fixed inset-0 bg-emerald-950/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4 print:bg-white">
          <div className="bg-white rounded-[4rem] w-full max-w-6xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl print:shadow-none animate-in slide-in-from-bottom-4 duration-500">
            <div className="p-12 bg-emerald-950 text-white flex justify-between items-start shrink-0 print:bg-white print:text-black">
              <div className="flex flex-col gap-8">
                <div className="bg-white p-4 rounded-2xl w-fit shadow-2xl print:shadow-none">
                   <img 
                     src={LOCAL_LOGO} 
                     alt="RPME" 
                     className="h-20 w-auto object-contain"
                     onError={(e) => {
                       const target = e.currentTarget;
                       if (target.src.includes('logo.png')) {
                         target.src = GITHUB_LOGO;
                       } else {
                         target.onerror = null;
                         target.src = "https://placehold.co/400x200/064e3b/ffffff?text=RPME+LIMITED";
                       }
                     }}
                   />
                </div>
                <div>
                  <h3 className="text-3xl font-black uppercase tracking-tighter">{selectedClient["Client Name"]}</h3>
                  <p className="text-[10px] text-emerald-400 uppercase font-black tracking-[0.3em] mt-2">Compliance Profile Registry • Ref: {selectedClient["No"]}</p>
                </div>
              </div>
              <div className="flex items-center gap-4 print:hidden">
                 <button onClick={handlePrint} className="flex items-center gap-2 bg-emerald-800 hover:bg-emerald-700 px-6 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all">
                    <Printer size={18}/> Official Export
                 </button>
                 <button onClick={() => setSelectedClient(null)} className="p-3 hover:bg-white/10 rounded-full transition-all cursor-pointer"><X size={32}/></button>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-12 space-y-12 custom-scrollbar bg-gray-50/20">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                  <div className="bg-white p-10 rounded-[3rem] border border-gray-100 shadow-sm space-y-6">
                    <h4 className="text-[10px] font-black text-emerald-800 uppercase tracking-[0.3em] border-b pb-4 flex items-center gap-3">
                      <Landmark size={20}/> Legal Basis
                    </h4>
                    <div className="grid grid-cols-2 gap-8">
                      <div><p className="text-[9px] text-gray-400 font-black uppercase tracking-widest mb-1">Origin</p><p className="text-md font-black text-emerald-950">{selectedClient["Company Nationality"]}</p></div>
                      <div><p className="text-[9px] text-gray-400 font-black uppercase tracking-widest mb-1">Status</p><p className="text-md font-black text-emerald-950">{selectedClient.kyc_status}</p></div>
                    </div>
                  </div>
                  <div className="bg-white p-10 rounded-[3rem] border border-gray-100 shadow-sm flex items-center justify-center">
                      <div className={`text-center p-8 rounded-[2.5rem] border-4 flex-1 ${selectedClient.riskLevel === RiskLevel.HIGH ? 'bg-red-50 border-red-200 text-red-900' : 'bg-emerald-50 border-emerald-100 text-emerald-900'}`}>
                         <p className="text-[10px] font-black uppercase tracking-widest mb-2 opacity-50">Risk Classification</p>
                         <p className="text-3xl font-black tracking-tight uppercase">{selectedClient.riskLevel}</p>
                      </div>
                  </div>
               </div>
            </div>

            <div className="p-12 bg-white border-t flex justify-end gap-4 print:hidden">
               <button onClick={() => setSelectedClient(null)} className="bg-emerald-950 text-white px-16 py-5 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-emerald-900 transition-all shadow-2xl active:scale-95 cursor-pointer">Return to Registry</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ClientManager;
